import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { NbComponentShape, NbTagAppearance } from '@nebular/theme';

@Component({
  selector: 'ngx-tag',
  templateUrl: './tag.component.html',
  styleUrls: ['./tag.component.scss'],
})
export class TagComponent implements OnInit, OnDestroy {
  @Input() icon: string = ''; // font-awesome or eva
  @Input() text: string = '';
  @Input() color: string = 'primary'; // hex or status
  @Input() shape: NbComponentShape = 'rectangle';
  @Input() appearance: NbTagAppearance = 'outline';
  @Input() isEvaIcon: boolean = false;

  constructor() {}
  ngOnInit(): void {}

  ngOnDestroy(): void {}

  public hexToRgbA(hex: string | undefined): string {
    var c: any;
    if (hex) {
      if (/^#([A-Fa-f0-9]{3}){1,2}$/.test(hex)) {
        c = hex.substring(1).split('');
        if (c.length == 3) {
          c = [c[0], c[0], c[1], c[1], c[2], c[2]];
        }
        c = '0x' + c.join('');

        return (
          'rgba(' +
          [(c >> 16) & 255, (c >> 8) & 255, c & 255].join(',') +
          ',0.08)'
        );
      }

      return '';
    }

    return '';
  }
}
