import { FileData } from '../../models/file-card.model';
import { GridColumn } from '../../models/grid-column.model';
import { IGridExportHeader } from '../../models/grid.model';
import { DATE_FORMATS } from '../../resources/defaults';
import { GRID_DATA_TYPE } from '../../resources/mode-enums';

export abstract class GridExport {
  /*
        Configures export headers as IGridExportHeader[] from table column settings.
    */
  public static configureIGridExportHeaders(
    columns: GridColumn[]
  ): IGridExportHeader[] {
    var headers: IGridExportHeader[] = [];

    columns.forEach((column: GridColumn) => {
      let format = DATE_FORMATS.date;
      switch (column.getType()) {
        case GRID_DATA_TYPE.DATE:
          format = column.getTypeSettings().getFormat();
          break;
        case GRID_DATA_TYPE.DATERANGE:
          format = column.getTypeSettings().getFormat();
          break;
        case GRID_DATA_TYPE.LOOKUP:
          format = column.getTypeSettings().getLookupColumn();
          break;
        case GRID_DATA_TYPE.TAG:
          format = column.getTypeSettings().getLookupColumn();
          break;
      }

      if (column.getExport()) {
        headers.push({
          property: column.getDataField(),
          headerToShow: column.getTitle(),
          export: column.getExport(),
          columnType: column.getType(),
          specialType: column.getType(),
          format: format,
        });
      }
    });

    return headers;
  }

  /*
        Gets filenames from item and header.
    */
  public static getFilename(item: any, header: IGridExportHeader): string {
    var text = '';

    if (item[header.property]) {
      if (Array.isArray(item[header.property])) {
        item[header.property].forEach((element: FileData) => {
          text = text + element.filename + '; ';
        });
      } else {
        text = item[header.property].filename;
      }
    }

    return text;
  }
}
