import { EDITORS_CONF } from '../resources/defaults';
import { GRID_DATE_PICKER, GRID_DATA_TYPE } from '../resources/mode-enums';

export abstract class GridColumnFilter {
  private _Show: boolean = true;
  protected _Type: GRID_DATA_TYPE = GRID_DATA_TYPE.TEXTBOX;
  protected _DataSource: any[] = [];
  protected _KeyExpression: string = '';
  protected _DisplayExpression: string = '';
  protected _ServerDataSource: boolean = false;
  protected _ServerEndpoint: string = '';
  protected _ServerMethod: string = '';
  protected _ServerParams: any = {};
  protected _ClearText: string = '';
  protected _Min: number | undefined | Date = undefined;
  protected _Max: number | undefined | Date = undefined;
  protected _DatePickerType: GRID_DATE_PICKER = GRID_DATE_PICKER.DATE;
  protected _Format: string = 'dd.MM.yyyy';
  protected _FilterDates: any = undefined;
  protected _ShowNavigation: boolean = true;
  protected _ShowWeekNumbers: boolean = false;
  protected _SingleColumn: boolean = true;
  protected _ShowSeconds: boolean = false;
  protected _TwelveHoursFormat: boolean = true;
  protected _TimeStep: number = EDITORS_CONF.timepickerStep;
  protected _ApplyButtonText: string = '';
  protected _CurrentTimeButtonText: string = '';
  protected _ShowCurrentTimeButton: boolean = true;
  protected _TimeText: string = '';
  protected _HoursText: string = '';
  protected _MinutesText: string = '';
  protected _SecondsText: string = '';
  protected _ShowFooter: boolean = true;

  constructor() {}

  public getTableSpecialFilter(): GRID_DATA_TYPE {
    return this._Type;
  }

  public getShow(): boolean {
    return this._Show;
  }

  public Show(x: boolean): GridColumnFilter {
    this._Show = x;
    return this;
  }

  public getDataSource(): any[] {
    return this._DataSource;
  }

  public getKeyExpression(): string {
    return this._KeyExpression;
  }

  public getDisplayExpression(): string {
    return this._DisplayExpression;
  }

  public getServerDataSource(): boolean {
    return this._ServerDataSource;
  }

  public getServerEndpoint(): string {
    return this._ServerEndpoint;
  }

  public getServerMethod(): string {
    return this._ServerMethod;
  }

  public getServerParams(): any {
    return this._ServerParams;
  }

  public getClearText(): string {
    return this._ClearText;
  }

  public getMin(): number | undefined | Date {
    return this._Min;
  }

  public getMax(): number | undefined | Date {
    return this._Max;
  }

  public getDatePickerType(): GRID_DATE_PICKER {
    return this._DatePickerType;
  }

  public getFormat(): string {
    return this._Format;
  }

  public getFilterDates(): any {
    return this._FilterDates;
  }

  public getShowNavigation(): boolean {
    return this._ShowNavigation;
  }

  public getShowWeekNumbers(): boolean {
    return this._ShowWeekNumbers;
  }

  public getSingleColumn(): boolean {
    return this._SingleColumn;
  }

  public getShowSeconds(): boolean {
    return this._ShowSeconds;
  }

  public getTwelveHoursFormat(): boolean {
    return this._TwelveHoursFormat;
  }

  public getTimeStep(): number {
    return this._TimeStep;
  }

  public getApplyButtonText(): string {
    return this._ApplyButtonText;
  }

  public getCurrentTimeButtonText(): string {
    return this._CurrentTimeButtonText;
  }

  public getShowCurrentTimeButton(): boolean {
    return this._ShowCurrentTimeButton;
  }

  public getTimeText(): string {
    return this._TimeText;
  }

  public getHoursText(): string {
    return this._HoursText;
  }

  public getMinutesText(): string {
    return this._MinutesText;
  }

  public getSecondsText(): string {
    return this._SecondsText;
  }

  public getShowFooter(): boolean {
    return this._ShowFooter;
  }
}

export class GridTextboxFilter extends GridColumnFilter {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.TEXTBOX;
  }
}

export class GridSelectFilter extends GridColumnFilter {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.SELECT;
    this._ServerDataSource = false;
    this._ServerMethod = 'GET';
  }

  public DataSource(x: any[]): GridSelectFilter {
    this._DataSource = x;
    return this;
  }

  public KeyExpression(x: string): GridSelectFilter {
    this._KeyExpression = x;
    return this;
  }

  public DisplayExpression(x: string): GridSelectFilter {
    this._DisplayExpression = x;
    return this;
  }

  public ServerDataSource(x: boolean): GridSelectFilter {
    this._ServerDataSource = x;
    return this;
  }

  public ServerEndpoint(x: string): GridSelectFilter {
    this._ServerEndpoint = x;
    return this;
  }

  public ServerMethod(x: string): GridSelectFilter {
    this._ServerMethod = x;
    return this;
  }

  public ServerParams(x: any): GridSelectFilter {
    this._ServerParams = x;
    return this;
  }

  public ClearText(x: string): GridSelectFilter {
    this._ClearText = x;
    return this;
  }
}

