import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import { GridColumn } from '../../models/grid-column.model';
import { GridComponent } from '../../grid/grid.component';
import { IGridSelection } from '../../models/grid.model';

@Component({
  selector: 'ngx-select-grid-popover',
  templateUrl: './select-grid-popover.component.html',
  styleUrls: ['./select-grid-popover.component.scss'],
})
export class SelectGridPopoverComponent implements AfterViewInit, OnInit {
  @Input() public width: number = 0;
  @Input() public selectGridId: string = '';
  @Input() public columns: GridColumn[] = [];
  @Input() public multiple: boolean = false;
  @Input() public source: any[] = [];
  @Input() public searchEnabled: boolean = false;
  @Input() public selected: any;
  @Input() public valueAttr: string = '';

  @ViewChild(GridComponent) grid!: GridComponent;

  @Output() gridSelectionChanged: EventEmitter<IGridSelection> =
    new EventEmitter();

  constructor(private ref: ElementRef) {}

  ngOnInit(): void {}

  ngAfterViewInit(): void {
    this.ref.nativeElement
      .closest('nb-popover')
      .classList.add('select-grid-nb-popover');

    if (this.selected && this.grid) {
      this.grid.unselectAll();
      this.grid.selectRows(this.selected, this.valueAttr);
    }
  }

  public selectionChanged(event: IGridSelection) {
    this.gridSelectionChanged.emit(event);
  }
}
