import { EventEmitter } from '@angular/core';
import { GridColumn } from '../../models/grid-column.model';
import {
  IGridDeletePopupSettings,
  IGridRowMenuItem,
} from '../../models/grid.model';

export abstract class GridPopup {
  private static fileMenuItemClick: EventEmitter<IGridRowMenuItem> =
    new EventEmitter();

  public static getFileMenuItemClickEvent(): EventEmitter<IGridRowMenuItem> {
    return this.fileMenuItemClick;
  }

  public static emitFileMenuItemClickEvent(model: IGridRowMenuItem): void {
    this.fileMenuItemClick.emit(model);
  }

  public static getPopupConfiguration(
    isNew: boolean,
    editRecordTitle: string | undefined,
    columns: GridColumn[],
    data: any,
    saveBtnTitle: string | undefined,
    cancelBtnTitle: string | undefined,
    showMinimizeBtn: boolean,
    showMaximizeBtn: boolean,
    showFullScreenBtn: boolean,
    hasBacktrop: boolean,
    closeOnBackdropClick: boolean,
    closeOnEscClick: boolean,
    requiredTooltip: string | undefined
  ): any {
    var conf: any = {
      title: editRecordTitle,
      context: {
        isNew: isNew,
        columns: columns,
        data: data,
        saveBtnText: saveBtnTitle,
        cancelBtnText: cancelBtnTitle,
        reqiredTooltip: requiredTooltip,
      },
      buttons: {
        minimize: showMinimizeBtn,
        maximize: showMaximizeBtn,
        fullScreen: showFullScreenBtn,
        close: true,
      },
      hasBackdrop: hasBacktrop,
      closeOnBackdropClick: closeOnBackdropClick,
      closeOnEsc: closeOnEscClick,
      windowClass: 'popup-window',
    };

    return conf;
  }

  public static getDeletePopupConfiguration(
    deletePopupSettings: IGridDeletePopupSettings
  ): any {
    var conf: any = {
      context: {
        settings: deletePopupSettings,
      },
      autoFocus: false,
      closeOnBackdropClick: deletePopupSettings.closeOnBackdropClick,
      closeOnEsc: deletePopupSettings.closeOnEsc,
    };

    return conf;
  }
}
