import { WINDOW_SIZE } from '../resources/defaults';
import { getError } from '../resources/error-codes';
import { PREVIEWABLE_EXTENSIONS } from '../resources/extensions';

/* 
    Generates unique id. 
    Important if multiple elements of same type are initialized. 
*/
export function makeId(length: number): string {
  var result = '';
  var characters =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  var charactersLength = characters.length;
  for (var i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * charactersLength));
  }

  return result;
}

/*
    Downloads selected file with file data provided in base64 format, and provided filename
*/
export function fileDownload(fileData: any, filename: string): void {
  fileData = fileData.substr(fileData.indexOf(',') + 1);
  fileData = base64ToArrayBuffer(fileData);
  const blob = new Blob([fileData], { type: 'application/octet-stream' });
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.download = filename;
  anchor.href = url;
  anchor.click();
}

/*
    Converts base64 to arrayBuffer.
*/
export function base64ToArrayBuffer(base64: any): ArrayBufferLike {
  var binary_string = window.atob(base64);
  var len = binary_string.length;
  var bytes = new Uint8Array(len);
  for (var i = 0; i < len; i++) {
    bytes[i] = binary_string.charCodeAt(i);
  }
  return bytes.buffer;
}

/*
    Starts preview file in new window based on file type.
    Avaliable types for preview are pdf, jpeg, jpg and png for now.
    Function requires file in base64 format.
*/
export function previewFile(
  base64: string,
  fileType: string,
  filename: string,
  windowWidth: number = WINDOW_SIZE.width,
  windowHeight: number = WINDOW_SIZE.height
) {
  var previewableExtensions = PREVIEWABLE_EXTENSIONS;

  if (
    previewableExtensions.find(
      (x: any) => x.extension == fileType.toLowerCase()
    )
  ) {
    var fileObj = previewableExtensions.find(
      (x: any) => x.extension == fileType.toLowerCase()
    );
    var type = fileObj?.type;

    if (fileObj!.extension == 'pdf') {
      var byteCharacters = atob(base64);
      var byteNumbers = new Array(byteCharacters.length);

      for (var i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }

      var byteArray = new Uint8Array(byteNumbers);

      var file = new Blob([byteArray], { type: type });
      var fileURL = URL.createObjectURL(file);

      popupCenter(fileURL, filename, windowWidth, windowHeight);
    } else {
      var w = popupCenter('about:blank', filename, windowWidth, windowHeight);

      setTimeout(function () {
        //FireFox seems to require a setTimeout for this to work.
        var element = w!.document.createElement('iframe');
        element.style.height = '100%';
        element.style.width = '100%';
        w!.document.body.appendChild(element).src = type + ',' + base64;
      }, 0);
    }
  } else {
    console.error(getError(101));
  }
}

/*
    Starts new browser window in the middle of screen.
*/
export function popupCenter(url: string, title: string, w: number, h: number) {
  const dualScreenLeft =
    window.screenLeft !== undefined ? window.screenLeft : window.screenX;
  const dualScreenTop =
    window.screenTop !== undefined ? window.screenTop : window.screenY;

  const width = window.innerWidth
    ? window.innerWidth
    : document.documentElement.clientWidth
    ? document.documentElement.clientWidth
    : screen.width;
  const height = window.innerHeight
    ? window.innerHeight
    : document.documentElement.clientHeight
    ? document.documentElement.clientHeight
    : screen.height;

  const systemZoom = width / window.screen.availWidth;
  const left = (width - w) / 2 / systemZoom + dualScreenLeft;
  const top = (height - h) / 2 / systemZoom + dualScreenTop;
  const newWindow = window.open(
    url,
    title,
    `
      scrollbars=yes,
      width=${w / systemZoom}, 
      height=${h / systemZoom}, 
      top=${top}, 
      left=${left}
      `
  );

  newWindow?.focus();
  return newWindow;
}

export function stringIsEmpty(str: string) {
  return !str || str.length === 0;
}

export function pushToArrayAtIndexRange(
  arrayA: any,
  arrayB: any,
  startIndex: number
) {
  // Check if the start index is valid
  if (startIndex < 0 || startIndex > arrayA.length) startIndex = 1;

  // Use splice to insert elements from arrayB into arrayA
  arrayA.splice(startIndex, 0, ...arrayB);
}
