import { Component, Input, OnInit } from '@angular/core';
import { NbComponentSize } from '@nebular/theme';
import { makeId } from '../functions/functions';
import { PROGRESSBAR_SPINNER_CONF } from '../resources/defaults';
import { TranslationService } from '../resources/translation.service';
import { strings } from '../resources/strings';

@Component({
  selector: 'ngx-progressbar-spinner',
  templateUrl: './progressbar-spinner.component.html',
  styleUrls: ['./progressbar-spinner.component.scss'],
})
export class ProgressbarSpinnerComponent implements OnInit {
  // ----------------------------------------------------- PRIVATE FIELDS ------------------------------------------------------

  // ----------------------------------------------------- PUBLIC FIELDS -------------------------------------------------------

  public id: string = 'progressbar-spinner-' + makeId(15); // unique component id

  // ----------------------------------------------------- COMPONENT CONSTRUCTION ----------------------------------------------

  constructor(private _translationService: TranslationService) {}

  ngOnInit(): void {
    // check if translations are already loaded (from external app)
    if (!this._translationService.isTranslationsLoaded()) {
      this._translationService.setTranslations(strings);
    }
  }

  // ----------------------------------------------------- INPUTS --------------------------------------------------------------

  @Input() public loading: boolean = false; // shows/hides progressbar spinner
  @Input() public status: string = PROGRESSBAR_SPINNER_CONF.status; // status color of progressbar and spinner
  @Input() public size: NbComponentSize = 'large'; // size of progressbar and spinner
  @Input() public message: string =
    this._translationService.translate('psLoading'); // spinner message, empty string disabled message
  @Input() public value: number = 0; // value of progressbar
  @Input() public displayValue: boolean = false; // shows/hides percentage indicator on progressbar
  @Input() public progressbarSize: string =
    PROGRESSBAR_SPINNER_CONF.progressbarSize; // class for progressbar size, bootstrap values (ex. col-md-10, col-3, col-sm-4)

  // ----------------------------------------------------- OUTPUTS -------------------------------------------------------------

  // ----------------------------------------------------- PRIVATE METHODS -----------------------------------------------------

  // ----------------------------------------------------- PUBLIC METHODS ------------------------------------------------------

  // ----------------------------------------------------- DOM LISTENERS -------------------------------------------------------
}
