import {
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnInit,
  Output,
  Pipe,
  PipeTransform,
  ViewChild,
} from '@angular/core';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { getError } from '../resources/error-codes';
import { FILE_SIZES } from '../resources/defaults';
import { TranslationService } from '../resources/translation.service';

@Component({
  selector: 'ngx-filepicker',
  templateUrl: './filepicker.component.html',
  styleUrls: ['./filepicker.component.scss'],
})
export class FilepickerComponent implements OnInit {
  constructor(private _translationService: TranslationService) {}

  ngOnInit(): void {}

  @HostBinding('class.disabled')
  @Input()
  get disabled() {
    return this._disabled;
  }
  set disabled(val: boolean) {
    this._disabled = coerceBooleanProperty(val);
  }
  @Input()
  set multiple(value: boolean) {
    this._multiple = coerceBooleanProperty(value);
  }
  get multiple() {
    return this._multiple;
  }

  @Input()
  set displayFileSize(value: boolean) {
    this._displayFileSize = coerceBooleanProperty(value);
  }
  get displayFileSize() {
    return this._displayFileSize;
  }

  get files() {
    return this._files;
  }

  public fileCount: number = 0;

  @Input()
  public maxFiles?: number;

  @Input()
  set showAcceptedFormats(value: boolean) {
    this._showAcceptedFormats = coerceBooleanProperty(value);
  }
  get showAcceptedFormats() {
    return this._showAcceptedFormats;
  }

  @Input()
  set showMaxFilesNumber(value: boolean) {
    this._showMaxFilesNumber = coerceBooleanProperty(value);
  }
  get showMaxFilesNumber() {
    return this._showMaxFilesNumber;
  }

  @HostBinding('class.empty-input')
  get isEmpty() {
    return !this.files?.length;
  }

  get isDragover() {
    return this._isDragOver;
  }
  set isDragover(value: boolean) {
    if (!this.disabled) {
      this._isDragOver = value;
    }
  }

  @Output()
  private valueChanged = new EventEmitter<File[]>();

  @ViewChild('fileInputEl')
  private fileInputEl?: ElementRef;

  @Input() accept = this._translationService.translate('filepickerAccept');

  private _disabled = false;

  _multiple = false;

  @Input() emptyPlaceholder =
    this._translationService.translate('filepickerEmpty');

  @Input() buttonPlaceholder =
    this._translationService.translate('filepickerButton');

  @Input() maxFilesPlaceholder =
    this._translationService.translate('filepickerMaxFiles');

  @Input() allowedFilesPlaceholder = this._translationService.translate(
    'filepickerAllowedFiles'
  );

  @Input() maxFilesWarningMessage = this._translationService.translate(
    'filepickerMaxFilesWarning'
  );

  private _displayFileSize = false;
  private _showAcceptedFormats = false;
  private _showMaxFilesNumber = false;

  private _files: File[] = [];
  private _isDragOver = false;

  private _onChange = (val: File[]) => {};
  private _onTouched = () => {};

  writeValue(files: File[]): void {
    const fileArray = this.convertToArray(files);
    if (fileArray.length < 2 || this.multiple) {
      if (this.maxFiles) {
        if (fileArray.length <= this.maxFiles) {
          this._files = fileArray;
          this.emitChanges(this._files);
        }
      } else {
        this._files = fileArray;
        this.emitChanges(this._files);
      }
    } else {
      throw Error(getError(102));
    }
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState?(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  private emitChanges(files: File[]) {
    this.valueChanged.emit(files);
    this._onChange(files);
  }

  addFiles(files: File[] | FileList | File) {
    const fileArray = this.convertToArray(files);
    if (this.multiple) {
      const merged = this.files.concat(fileArray);
      this.writeValue(merged);
    } else {
      this.writeValue(fileArray);
    }
  }

  removeFile(file: File) {
    const fileIndex = this.files.indexOf(file);
    if (fileIndex >= 0) {
      const currentFiles = this.files.slice();
      currentFiles.splice(fileIndex, 1);
      this.writeValue(currentFiles);
    }
  }

  clear() {
    this.writeValue([]);
  }

  @HostListener('change', ['$event'])
  change(event: Event) {
    event.stopPropagation();
    this._onTouched();
    const fileList: FileList | null = (event.target as HTMLInputElement).files;
    if (fileList?.length) {
      this.addFiles(fileList);
    }
    (event.target as HTMLInputElement).value = '';
  }

  @HostListener('dragenter', ['$event'])
  @HostListener('dragover', ['$event'])
  activate(e: any) {
    e.preventDefault();
    this.isDragover = true;
  }

  @HostListener('dragleave', ['$event'])
  deactivate(e: any) {
    e.preventDefault();
    this.isDragover = false;
  }

  @HostListener('drop', ['$event'])
  handleDrop(e: any) {
    this.deactivate(e);
    if (!this.disabled) {
      const fileList = e.dataTransfer.files;
      this.removeDirectories(fileList).then((files: any) => {
        if (files?.length) {
          this.addFiles(files);
        }
        this._onTouched();
      });
    }
  }

  @HostListener('click')
  open() {
    if (!this.disabled) {
      this.fileInputEl?.nativeElement.click();
    }
  }

  private removeDirectories(files: FileList) {
    return new Promise((resolve, reject) => {
      const fileArray = this.convertToArray(files);
      const dirnames: string[] = [];
      const readerList = [];
      for (let i = 0; i < fileArray.length; i++) {
        const reader = new FileReader();
        reader.onerror = () => {
          dirnames.push(fileArray[i].name);
        };
        reader.onloadend = () => addToReaderList(i);
        reader.readAsArrayBuffer(fileArray[i]);
      }

      function addToReaderList(val: number) {
        readerList.push(val);
        if (readerList.length === fileArray.length) {
          resolve(
            fileArray.filter((file: File) => !dirnames.includes(file.name))
          );
        }
      }
    });
  }

  private convertToArray(
    files: FileList | File[] | File | null | undefined
  ): File[] {
    if (files) {
      if (files instanceof File) {
        return [files];
      } else if (Array.isArray(files)) {
        return files;
      } else {
        return Array.prototype.slice.call(files);
      }
    }
    return [];
  }

  getFileName(file: File): string {
    if (!this._displayFileSize) {
      return file.name;
    }
    const size = new BytePipe().transform(file.size);
    return `${file.name} (${size})`;
  }
}

@Pipe({
  name: 'byte',
})
export class BytePipe implements PipeTransform {
  private unit = 'Bytes';
  transform(value: string | number, decimals?: number | string): string {
    value = value.toString();
    if (parseInt(value, 10) >= 0) {
      value = this.formatBytes(+value, +decimals!);
    }
    return value;
  }

  formatBytes(bytes: number, decimals = 2): string {
    if (bytes === 0) {
      return '0 Bytes';
    }
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = FILE_SIZES;
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
  }
}
