import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { GRID_CONF } from '../../resources/defaults';

@Component({
  selector: 'ngx-grid-footer',
  templateUrl: './grid-footer.component.html',
  styleUrls: ['./grid-footer.component.scss'],
})
export class GridFooterComponent implements OnInit {
  constructor() {}

  ngOnInit(): void {}

  @Input() entriesPerPageOptions: number[] = GRID_CONF.entriesPerPageOptions;
  @Input() visible: boolean = true;
  @Input() set page(value: number) {
    this._page = value;
    this.pageChange.emit(this._page);
  }
  get page(): number {
    return this._page;
  }
  @Input() refreshEnabled: boolean = true;
  @Input() public refreshTooltip: string = ''; // tooltip to be shown on Refresh button hover -> empty string disables tooltip
  @Input() exportPdfEnabled: boolean = true;
  @Input() public exportPdfTooltip: string = ''; // tooltip to be shown on PDF export button hover -> empty string disables tooltip
  @Input() exportExcelEnabled: boolean = true;
  @Input() public exportExcelTooltip: string = ''; // tooltip to be shown on Excel export button hover -> empty string disables tooltip
  @Input() entriesPerPageEnabled: boolean = true;
  @Input() public entriesPerPageTooltip: string = ''; // tooltip to be shown on entries per page hover -> empty string disables tooltip
  @Input() set defaultPerPageOption(value: number) {
    this._defaultPerPageOption = value;
    this.defaultPerPageOptionChange.emit(this._defaultPerPageOption);
  }
  get defaultPerPageOption(): number {
    return this._defaultPerPageOption;
  }

  private _page: number = 1;
  private _defaultPerPageOption: number =
    this.entriesPerPageOptions?.length > 0
      ? this.entriesPerPageOptions[0]
      : GRID_CONF.defaultEntriesPerPage;

  @Output() defaultPerPageOptionChange: EventEmitter<number> =
    new EventEmitter<number>();
  @Output() pageChanged = new EventEmitter();
  @Output() resetFiltersClicked = new EventEmitter();
  @Output() exportPdfClicked = new EventEmitter();
  @Output() exportExcelClicked = new EventEmitter();
  @Output() selectionPerPageChanged = new EventEmitter<number>();
  @Output() pageChange: EventEmitter<number> = new EventEmitter<number>();

  public onPageChanged() {
    this.pageChanged.emit();
  }

  public onClickResetFilters() {
    this.resetFiltersClicked.emit();
  }

  public exportPdfBtnClick() {
    this.exportPdfClicked.emit();
  }

  public exportExcelBtnClick() {
    this.exportExcelClicked.emit();
  }

  public onSelectedChangePagerPerPage(page: number) {
    this.selectionPerPageChanged.emit(page);
  }
}
