import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { KeyValue } from './strings';

@Injectable({
  providedIn: 'root',
})
export class TranslationService {
  private translations: KeyValue[] = [];
  private map = new Map<string, string>();

  constructor(private http: HttpClient) {}

  loadTranslations(url: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      this.http
        .get<KeyValue[]>(url)
        .toPromise()
        .then(
          (translations) => {
            this.setTranslations(translations);
            resolve();
          },
          (error) => {
            console.error('Error loading translations:', error);
            reject(error);
          }
        );
    });
  }

  setTranslations(translations: KeyValue[]) {
    this.translations = translations;
    this.map = new Map(this.translations.map((obj) => [obj.key, obj.value]));
  }

  translate(key: string): string {
    return this.map.get(key) || key;
  }

  isTranslationsLoaded(): boolean {
    return this.translations.length > 0;
  }
}
