import { HttpClient, HttpParams } from '@angular/common/http';
import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import {
  NbMenuItem,
  NbMenuService,
  NbRevealCardComponent,
} from '@nebular/theme';
import { Subscription } from 'rxjs';
import { filter, map } from 'rxjs/operators';
import { fileDownload, makeId, previewFile } from '../functions/functions';
import { FileData } from '../models/file-card.model';
import { DATE_FORMATS, ICONS } from '../resources/defaults';
import { getError } from '../resources/error-codes';
import {
  ExtensionIcon,
  KNOWN_EXTENSIONS,
  UNKNOWN_EXTENSION,
} from '../resources/extensions';
import { FILE_CARD_MODE, FILE_MENU_CODES } from '../resources/mode-enums';
import { TranslationService } from '../resources/translation.service';

@Component({
  selector: 'ngx-file-card',
  templateUrl: './file-card.component.html',
  styleUrls: ['./file-card.component.scss'],
})
export class FileCardComponent implements OnInit, OnDestroy {
  // -------------------------------------------------- PUBLIC FIELDS ----------------------------------------------------------------------

  public id: string = 'file-card-' + makeId(15); // unique component id
  public menuItems: NbMenuItem[] = []; // items to show in file context menu
  public menuId: string = 'file-more-menu-' + makeId(15); // component unique id
  public extension: ExtensionIcon = UNKNOWN_EXTENSION; // extension data to show in card icon
  public fileCardModes = FILE_CARD_MODE; // card modes enum for HTML switch

  // -------------------------------------------------- PRIVATE FIELDS ---------------------------------------------------------------------

  private knownExtensions: ExtensionIcon[] = KNOWN_EXTENSIONS; // list of extesions supported
  private subscriptions: Subscription[] = [];

  // -------------------------------------------------- INPUTS -----------------------------------------------------------------------------

  @Input() public canDownload: boolean = true; // shows/hides download option in file context menu
  @Input() public canPreview: boolean = true; // shows/hides preview option in file context menu
  @Input() public canDelete: boolean = true; // shows/hides delete option in file context menu
  @Input() public deleteTitle: string =
    this.translationService.translate('fileDelete'); // title for delete option in file context menu
  @Input() public previewTitle: string =
    this.translationService.translate('filePreview'); // title for preview option in file context menu
  @Input() public downloadTitle: string =
    this.translationService.translate('fileDownload'); // title for download option in file context menu
  @Input() public custumFileActions: NbMenuItem[] = []; // list of custom actions in file context menu
  @Input() public sizeTitle: string =
    this.translationService.translate('fileSize'); // title for size attribute in file card details
  @Input() public detailsEnabled: boolean = true; // shows/hides file details section
  @Input() public authorTitle: string =
    this.translationService.translate('fileAuthor'); // title for author attribute in file card details
  @Input() public filenameTitle: string =
    this.translationService.translate('fileName'); // title for file name in file card details
  @Input() public extensionTitle: string =
    this.translationService.translate('fileExtension'); // title for extension in file card details
  @Input() public dateTitle: string =
    this.translationService.translate('fileDate'); // title for date in file card details
  @Input() public mode: FILE_CARD_MODE = FILE_CARD_MODE.CARD; // file card mode, can be card, table, row or small card
  @Input() public useCustomPreview: boolean = false; // enables/disables built in file preview, if disabled only menuItemClick event is fired
  @Input() public useCustomDownload: boolean = false; // enables/disables built in file download, if disabled only menuItemClick event is fired
  @Input() public fileFromServer: boolean = false; // indicates file download/preview is from server
  @Input() public serverEndpoint: string | undefined = undefined; // server endpoint URL
  @Input() public keyAttribute: string | undefined = undefined; // name of key attribute to be sent to server as parameter
  @Input() public bytesAttribute: string | undefined = undefined; // name of attribute in which base64 of file is stored (only for files coming from server)
  @Input() public formatDate: boolean = false; // enables/disables date formating
  @Input() public dateFromat: string = DATE_FORMATS.dateTime; // date format to use for formatting
  @Input() public useBrandColors: boolean = true; // color logos of known brand extesions

  @Input() public fileData: FileData = {
    // data to be shown
    id: '', // key of file
    filename: '', // name of file
    extension: '', // file type (extension)
  };

  // -------------------------------------------------- OUTPUTS ----------------------------------------------------------------------------

  @Output() fileMenuItemClick: EventEmitter<NbMenuItem> = new EventEmitter(); // fired when file context menu item is clicked, provides data about item selected

  // -------------------------------------------------- VIEW CHILD -------------------------------------------------------------------------

  @ViewChild(NbRevealCardComponent) revealCard!: NbRevealCardComponent;

  // -------------------------------------------------- COMPONENT CONSTRUCTION -------------------------------------------------------------

  constructor(
    private menuService: NbMenuService,
    private http: HttpClient,
    private translationService: TranslationService
  ) {}

  ngOnInit(): void {
    if (this.canDownload)
      this.menuItems.push({
        title: this.downloadTitle,
        icon: ICONS.download,
        data: { code: FILE_MENU_CODES.DOWNLOAD },
      });
    if (this.canPreview)
      this.menuItems.push({
        title: this.previewTitle,
        icon: ICONS.preview,
        data: { code: FILE_MENU_CODES.PREVIEW },
      });
    if (this.canDelete)
      this.menuItems.push({
        title: this.deleteTitle,
        icon: ICONS.delete,
        data: { code: FILE_MENU_CODES.DELETE },
      });
    if (this.custumFileActions.length > 0)
      this.menuItems = this.menuItems.concat(this.custumFileActions);

    this.subscriptions.push(
      this.menuService
        .onItemClick()
        .pipe(
          filter(({ tag }) => {
            return tag?.indexOf(this.menuId) > -1;
          }),
          map(({ item }) => item)
        )
        .subscribe((item: NbMenuItem) => {
          item.data['file'] = this.fileData; // add file data to item.data, at this point file data is provided inside menu item clicked
          this.menuItemClick(item);
        })
    );

    var ext = this.knownExtensions.find(
      (x: any) => x.extension == this.fileData.extension?.toLowerCase()
    );
    if (ext) this.extension = ext;
    else this.extension = UNKNOWN_EXTENSION;
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((element) => {
      element.unsubscribe();
    });
  }

  // -------------------------------------------------- PRIVATE METHODS --------------------------------------------------------------------

  /*
    Performs menu item click.
    If built in functions for download and preview are used, downloads and displays file.
    Emits fileMenuItemClick output event with NbMenuItem data and file data.
  */
  private menuItemClick(item: NbMenuItem): void {
    switch (item.data.code) {
      case FILE_MENU_CODES.DOWNLOAD:
        if (!this.useCustomDownload) {
          // do built in download
          if (this.fileFromServer) {
            if (
              this.serverEndpoint &&
              this.bytesAttribute &&
              this.keyAttribute
            ) {
              var params = new HttpParams().append(
                this.keyAttribute,
                item.data.file[this.keyAttribute]
              );
              this.subscriptions.push(
                this.http
                  .get(this.serverEndpoint, { params: params })
                  .subscribe((file: any) => {
                    if (file)
                      fileDownload(
                        file[this.bytesAttribute!],
                        item.data.file.filename
                      );
                    else console.error(getError(105));
                  })
              );
            } else console.error(getError(103));
          } else {
            if (this.fileData.fileBytes)
              fileDownload(this.fileData.fileBytes, item.data.file.filename);
            else console.error(getError(106));
          }
        }

        break;

      case FILE_MENU_CODES.PREVIEW:
        if (!this.useCustomPreview) {
          // do built in preview
          if (this.fileFromServer) {
            if (
              this.serverEndpoint &&
              this.bytesAttribute &&
              this.keyAttribute
            ) {
              var params = new HttpParams().append(
                this.keyAttribute,
                item.data.file[this.keyAttribute]
              );
              this.subscriptions.push(
                this.http
                  .get(this.serverEndpoint, { params: params })
                  .subscribe((file: any) => {
                    if (file)
                      previewFile(
                        file[this.bytesAttribute!],
                        item.data.file.extension,
                        item.data.file.filename
                      );
                    else console.error(getError(105));
                  })
              );
            } else console.error(getError(104));
          } else {
            if (this.fileData.fileBytes)
              previewFile(
                this.fileData.fileBytes,
                item.data.file.extension,
                item.data.file.filename
              );
            else console.error(getError(106));
          }
        }

        break;
    }

    this.fileMenuItemClick.emit(item); // emit event click output with NbMenuItem data
  }

  // -------------------------------------------------- PUBLIC METHODS ---------------------------------------------------------------------

  // -------------------------------------------------- DOM LISTENERS ----------------------------------------------------------------------

  public onClickRevealCard(): void {
    this.revealCard.toggle();
  }

  /*
    If card mode is row, then actions are displayed as buttons.
    Function emits fileMenuItemClick output event on button click with NbMenuItem data and file data.
  */
  public onRowButtonClick(item: NbMenuItem) {
    item.data['file'] = this.fileData;
    this.menuItemClick(item);
  }
}
