import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
} from '@angular/core';
import { GridColumn } from '../../models/grid-column.model';
import { GRID_BUTTON_TYPE, GRID_DATA_TYPE } from '../../resources/mode-enums';
import { IGridCellButton } from '../../models/grid.model';
import { GridButtonType } from '../../models/grid-button-type.model';

@Component({
  selector: 'ngx-cell-display',
  templateUrl: './cell-display.component.html',
  styleUrls: ['./cell-display.component.scss'],
})
export class CellDisplayComponent implements OnInit, OnDestroy {
  constructor() {}

  ngOnInit(): void {
    if (this.column.getType() == GRID_DATA_TYPE.BUTTONS) {
      var dataField: string | boolean = this.column
        .getTypeSettings()
        .getButtonsFromDataField();
      this.buttons =
        dataField != false
          ? this.row[dataField.toString()]
          : this.column.getTypeSettings().getButtons();
    }
  }

  ngOnDestroy(): void {}

  @Input() column: GridColumn = new GridColumn();
  @Input() row: any = {};

  @Output() buttonClick: EventEmitter<IGridCellButton> = new EventEmitter();

  public types = GRID_DATA_TYPE;
  public btnTypes = GRID_BUTTON_TYPE;
  public buttons: GridButtonType[] = [];

  public hexToRgbA(hex: string | undefined): string {
    var c: any;
    if (hex) {
      if (/^#([A-Fa-f0-9]{3}){1,2}$/.test(hex)) {
        c = hex.substring(1).split('');
        if (c.length == 3) {
          c = [c[0], c[0], c[1], c[1], c[2], c[2]];
        }
        c = '0x' + c.join('');

        return (
          'rgba(' +
          [(c >> 16) & 255, (c >> 8) & 255, c & 255].join(',') +
          ',0.08)'
        );
      }

      return '';
    }

    return '';
  }

  public onButtonClick(btn: GridButtonType): void {
    this.buttonClick.emit({
      button: btn,
      row: this.row,
    });
  }
}
