import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
} from '@angular/core';
import { GridColumn } from '../../models/grid-column.model';
import { GRID_DATE_PICKER, GRID_DATA_TYPE } from '../../resources/mode-enums';
import { HttpClient } from '@angular/common/http';
import { Subscription } from 'rxjs';
import { getError } from '../../resources/error-codes';
import { IGridFilter } from '../../models/grid.model';
import { GridColumnFilter } from '../../models/grid-column-filter.model';
import { TranslationService } from '../../resources/translation.service';

@Component({
  selector: 'ngx-column-filter',
  templateUrl: './column-filter.component.html',
  styleUrls: ['./column-filter.component.scss'],
})
export class ColumnFilterComponent implements OnInit, OnDestroy {
  constructor(
    private http: HttpClient,
    private translationService: TranslationService
  ) {}

  ngOnInit(): void {
    if (this.column.getFilter() == GRID_DATA_TYPE.SELECT) {
      var settings = this.column.getFilterSettings();
      if (settings.getServerDataSource()) {
        // get data from server
        this.getDataSourceFromServer(settings);
      } else this.selectFilterDataSource = settings.getDataSource();
    }

    this.translateEditorDefaultOptions();
  }

  ngOnDestroy(): void {
    this._subs.forEach((element) => {
      element.unsubscribe();
    });
  }

  @Input() column: GridColumn = new GridColumn();

  @Output() filterChanged: EventEmitter<IGridFilter> =
    new EventEmitter<IGridFilter>();

  private _subs: Subscription[] = [];

  public types = GRID_DATA_TYPE;
  public selectFilterDataSource: any[] = [];
  public datePickerTypes = GRID_DATE_PICKER;
  public value: any;

  private getDataSourceFromServer(settings: GridColumnFilter): void {
    this._subs.push(
      this.http
        .get(settings.getServerEndpoint(), {
          params: settings.getServerParams(),
        })
        .subscribe((data: any) => {
          if (data) this.selectFilterDataSource = data;
          else console.error(getError(205));
        })
    );
  }

  public onFilterChanged(): void {
    this.filterChanged.emit({ column: this.column, filterValue: this.value });
  }

  public resetFilter(): void {
    this.value = null;
  }

  public onRangeChange(ev: any) {
    if (ev.start && ev.end) {
      this.value = ev;
      this.onFilterChanged();
    }
  }

  public rangePickerModelChange(ev: any): void {
    if (ev == null) {
      this.value = null;
      this.onFilterChanged();
    }
  }

  private translateEditorDefaultOptions() {
    var filter = this.column.getFilterSettings() as any;

    if (!filter._ClearText)
      filter._ClearText =
        this.translationService.translate('gridFilterShowAll');
    if (!filter._ApplyButtonText)
      filter._ApplyButtonText = this.translationService.translate(
        'gridDatepickerApplyBtn'
      );
    if (!filter._CurrentTimeButtonText)
      filter._CurrentTimeButtonText =
        this.translationService.translate('gridDatepickerNow');
    if (!filter._TimeText)
      filter._TimeText =
        this.translationService.translate('gridDatepickerAmPm');
    if (!filter._HoursText)
      filter._HoursText = this.translationService.translate(
        'gridDatepickerHours'
      );
    if (!filter._MinutesText)
      filter._MinutesText = this.translationService.translate(
        'gridDatepickerMinutes'
      );
    if (!filter._SecondsText)
      filter._SecondsText = this.translationService.translate(
        'gridDatepickerSeconds'
      );
  }
}
