import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  Input,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import { NbAccordionItemComponent, NbTagAppearance } from '@nebular/theme';
import { Observable, of } from 'rxjs';
import { map } from 'rxjs/operators';
import { makeId } from '../functions/functions';
import { AutocompleteSelectionModel } from '../models/tags-autocomplete.model';
import { TranslationService } from '../resources/translation.service';
import { strings } from '../resources/strings';

@Component({
  selector: 'ngx-tags-autocomplete',
  templateUrl: './tags-autocomplete.component.html',
  styleUrls: ['./tags-autocomplete.component.scss'],
})
export class TagsAutocompleteComponent implements OnInit, AfterViewInit {
  private clickInsideComponent = false;

  @HostListener('click')
  clickInside() {
    this.clickInsideComponent = true;
  }

  @HostListener('document:click')
  clickout() {
    if (!this.clickInsideComponent) {
      if (this.floatingDroopDown) this.accordionItem.close();
    }
    this.clickInsideComponent = false;
  }

  // ----------------------------------------------------- PRIVATE FIELDS ----------------------------------------------------------

  private _source: any[] = [];
  private _selectedKeys: any[] = [];

  // ----------------------------------------------------- VIEW CHILD --------------------------------------------------------------

  @ViewChild('autoInput') input!: ElementRef<any>;
  @ViewChild('headerTags') headerTags!: ElementRef<any>;
  @ViewChild('tagsAutocompleteAccordionItem')
  accordionItem!: NbAccordionItemComponent;

  // ----------------------------------------------------- INPUTS ------------------------------------------------------------------
  @Input()
  set source(value: any[]) {
    this._source = value;
    setTimeout(() => {
      this.syncSelection();
    }, 100);
  }
  get source(): any[] {
    return this._source;
  }

  @Input() set selectedKeys(value: any[]) {
    this._selectedKeys = value;
    this.selectedKeysChange.emit(this._selectedKeys);
  } // current selected keys, only if keyAttribute is set
  get selectedKeys(): any[] {
    return this._selectedKeys;
  }
  @Output() selectedKeysChange: EventEmitter<any> = new EventEmitter<any>();

  @Input() public selectedItems: any[] = []; // current selected items
  @Input() public keyAttribute: string | undefined = undefined; // name of key attribute for data selection
  @Input() public attributesToShow: string[] = []; // names of attributes to show in option
  @Input() public attributesToShowInTag: string[] = []; // names of attributes to show in tag
  @Input() public attributesToFilter: string[] = []; // names of attributes to filter data
  @Input() public emptyPlaceholder: string =
    this.translationService.translate('taEmptyPlaceholder'); // empty autocomplete placeholder
  @Input() public tagStatus: string = 'basic';
  @Input() public tagAppereance: NbTagAppearance = 'outline';
  @Input() public inputWidthClass: string = 'col-md-12'; // width class for autocomplete input field
  @Input() public inputPlaceholder: string =
    this.translationService.translate('taInputPlaceholder'); // placeholder for empty input field
  @Input() public clearEnabled: boolean = true; // shows/hides clear button
  @Input() public clearBtnTooltip: string =
    this.translationService.translate('taClearTooltip'); // clear button tooltip on hover
  @Input() public expanded: boolean = false; // expandes/collapses autocomplete element
  @Input() public displayArrow: boolean = false; // shows/hides arrow
  @Input() public displayNumSelected: boolean = false; // shows/hides number of selected items
  @Input() public displayDots: boolean = false; // shows/hides dots indicator for more
  @Input() public multiple: boolean = true; // multiple select or singe
  @Input() public floatingDroopDown: boolean = true; // displays dropdown as floating select box otherwise it expands content as an accordion
  @Input() public disabled: boolean = false; // enables/disables control

  // ----------------------------------------------------- PUBLIC FIELDS -----------------------------------------------------------

  public headerOverflown: boolean = false; // indicates if header of autocomplete has overflow
  public id = 'tag-autocomplete-' + makeId(15); // unique component id
  public filteredOptions$: Observable<string[]> = of(this.source); // filtered options for autocomplete

  // ----------------------------------------------------- OUTPUTS -----------------------------------------------------------------

  @Output()
  public onSelectionChanged: EventEmitter<AutocompleteSelectionModel> =
    new EventEmitter<AutocompleteSelectionModel>(); // fires on autocomplete selection
  @Output() public onOptionRemoved: EventEmitter<AutocompleteSelectionModel> =
    new EventEmitter<AutocompleteSelectionModel>(); // fires on tag remove
  @Output() public onSelectionCleared: EventEmitter<boolean> =
    new EventEmitter<boolean>(); // fires on clear button click

  // ----------------------------------------------------- COMPONENT CONSTRUCTION --------------------------------------------------

  constructor(private translationService: TranslationService) {}

  ngOnInit(): void {
    // check if translations are already loaded (from external app)
    if (!this.translationService.isTranslationsLoaded()) {
      this.translationService.setTranslations(strings);
    }

    this.syncSelection();

    // await for div to resize
    setTimeout(() => {
      this.headerOverflown = this.checkOverflow();
    }, 100);
  }

  ngAfterViewInit(): void {
    if (!this.displayArrow)
      document
        .querySelector('#' + this.id + ' .expansion-indicator')
        ?.classList.add('d-none');
    else
      document
        .querySelector('#' + this.id + ' .expansion-indicator')
        ?.classList.add('status-basic');
  }

  // ----------------------------------------------------- PRIVATE METHODS ---------------------------------------------------------

  private syncSelection() {
    if (this.selectedKeys == undefined) this.selectedKeys = [];
    else if (!Array.isArray(this.selectedKeys))
      this.selectedKeys = [this.selectedKeys];

    if (this.selectedItems || this.selectedKeys) {
      // sync selectedItems and selectedKeys
      if (this.keyAttribute) {
        // if both selectedItems and selectedKeys are set --> sync by selectedItems
        if (this.selectedItems.length > 0 && this.selectedKeys.length > 0) {
          this.selectedKeys = this.selectedItems.map(
            (x: any) => x[this.keyAttribute!]
          );
        }
        // if only selectedKeys is set --> sync by key
        else if (
          this.selectedKeys.length > 0 &&
          this.selectedItems.length == 0
        ) {
          this.selectedItems = this.source.filter((x: any) =>
            this.selectedKeys.includes(x[this.keyAttribute!])
          );
        }
        // if only selectedItems is set --> sync by items
        else if (
          this.selectedItems.length > 0 &&
          this.selectedKeys.length == 0
        ) {
          this.selectedKeys = this.selectedItems.map(
            (x: any) => x[this.keyAttribute!]
          );
        }
      }
    } else {
      this.clear();
    }
  }

  private filter(value: any): any[] {
    const filterValue = value.toLowerCase();
    return this.source.filter((o: any) =>
      Object.keys(o).some(
        (k) =>
          this.attributesToFilter.includes(k) &&
          o[k].toString().toLowerCase().includes(filterValue.toLowerCase())
      )
    );
  }

  private getFilteredOptions(value: any): Observable<string[]> {
    return of(value).pipe(map((filterString) => this.filter(filterString)));
  }

  // ----------------------------------------------------- PUBLIC METHODS ----------------------------------------------------------

  public getTagText(tag: any): string {
    var text = '';
    this.attributesToShowInTag.forEach((attribute: string) => {
      text = text + ' ' + tag[attribute];
    });

    return text;
  }

  public getOptionText(option: any): string {
    var text = '';
    this.attributesToShow.forEach((attribute: string) => {
      text = text + ' ' + option[attribute];
    });

    return text;
  }

  public clearInputValue(): void {
    this.input.nativeElement.value = '';
  }

  public showClearButton(): boolean {
    if (this.input) {
      if (this.input.nativeElement.value) return true;
      else return false;
    } else return false;
  }

  public checkOverflow(): boolean {
    if (this.headerTags) {
      return (
        this.headerTags.nativeElement.scrollHeight >
          this.headerTags.nativeElement.clientHeight ||
        this.headerTags.nativeElement.scrollWidth >
          this.headerTags.nativeElement.clientWidth
      );
    } else return false;
  }

  public getSelectedItems(): any[] {
    return this.selectedItems;
  }

  public getSelectedKeys(): any[] {
    return this.selectedKeys;
  }

  public clear(): void {
    this.selectedItems = [];
    this.selectedKeys = [];
    this.clearInputValue();
    this.onSelectionCleared.emit(true);
  }

  public setDataSource(source: any[]): void {
    this.source = source;
    this.filteredOptions$ = of(this.source);
  }

  // ----------------------------------------------------- DOM LISTENERS -----------------------------------------------------------

  public onChange(): void {
    this.filteredOptions$ = this.getFilteredOptions(
      this.input.nativeElement.value
    );
  }

  public onSelectionChange($event: any): void {
    this.clickInsideComponent = true;
    this.input.nativeElement.value = this.getOptionText($event);
    if (this.multiple) {
      if (!this.selectedItems.includes($event)) this.selectedItems.push($event);
      if (this.keyAttribute) {
        if (!this.selectedKeys.includes($event[this.keyAttribute]))
          this.selectedKeys.push($event[this.keyAttribute]);
        this.onSelectionChanged.emit({
          selectedItem: $event,
          selectedItemKey: $event[this.keyAttribute],
          currentSelectedItems: this.selectedItems,
          currentSelectedKeys: this.selectedKeys,
        });
      } else
        this.onSelectionChanged.emit({
          selectedItem: $event,
          currentSelectedItems: this.selectedItems,
        });
    } else {
      this.selectedItems = [];
      this.selectedItems.push($event);
      if (this.keyAttribute) {
        this.selectedKeys = [];
        this.selectedKeys.push($event[this.keyAttribute]);
        this.onSelectionChanged.emit({
          selectedItem: $event,
          selectedItemKey: $event[this.keyAttribute],
          currentSelectedItems: this.selectedItems,
          currentSelectedKeys: this.selectedKeys,
        });
      } else
        this.onSelectionChanged.emit({
          selectedItem: $event,
          currentSelectedItems: this.selectedItems,
        });
    }

    // await for div to resize
    setTimeout(() => {
      this.headerOverflown = this.checkOverflow();
    }, 100);
  }

  public onTagRemove(tag: any): void {
    this.selectedItems.splice(this.selectedItems.indexOf(tag), 1);
    if (this.keyAttribute) {
      this.selectedKeys.splice(
        this.selectedKeys.indexOf(tag[this.keyAttribute]),
        1
      );
      this.onOptionRemoved.emit({
        removedItem: tag,
        removedItemKey: tag[this.keyAttribute],
        currentSelectedItems: this.selectedItems,
        currentSelectedKeys: this.selectedKeys,
      });
    } else
      this.onOptionRemoved.emit({
        removedItem: tag,
        currentSelectedItems: this.selectedItems,
      });

    // await for div to resize
    setTimeout(() => {
      this.headerOverflown = this.checkOverflow();
    }, 100);
  }
}
