import { NbMenuItem } from '@nebular/theme';
import {
  GRID_DATA_TYPE,
  GRID_MENU_ACTION,
  GRID_SORT,
} from '../resources/mode-enums';
import {
  GridColumnFilter,
  GridTextboxFilter,
} from './grid-column-filter.model';
import { GridColumnType, GridTextColumn } from './grid-column-type.model';
import { makeId, stringIsEmpty } from '../functions/functions';
import {
  GridColumnEditor,
  GridTextboxEditor,
} from './grid-column-editor.model';

export class GridColumn {
  private _Id: string = makeId(50);
  private _Title: string = '';
  private _DataField: string = '';
  private _Type: GridColumnType = new GridTextColumn();
  private _Filter: GridColumnFilter = new GridTextboxFilter();
  private _Docked: boolean = false;
  private _Sortable: boolean = true;
  private _GroupingEnabled: boolean = true;
  private _SortState: GRID_SORT = GRID_SORT.NONE;
  private _ContextMenuId: string = makeId(20);
  private _ContextMenuItems: NbMenuItem[] = [];
  private _Editor: GridColumnEditor = new GridTextboxEditor();
  private _Export: boolean = true;
  private _Addable: boolean = true;
  private _Editable: boolean = true;
  private _Width: string = '';
  private _Visible: boolean = true;
  private _Index: number = 0;
  private _Grouped: boolean = false;
  private _ShowGroupCount: boolean = true;

  constructor() {
    this.setUpMenuItems();
  }

  public Title(title: string): GridColumn {
    this._Title = title;
    return this;
  }

  public getIndex(): number {
    return this._Index;
  }

  public Index(index: number): GridColumn {
    this._Index = index;
    return this;
  }

  public Addable(addable: boolean): GridColumn {
    this._Addable = addable;
    return this;
  }

  public Editable(editable: boolean): GridColumn {
    this._Editable = editable;
    return this;
  }

  public getAddable(): boolean {
    return this._Addable;
  }

  public getEditable(): boolean {
    return this._Editable;
  }

  public getTitle(): string {
    return this._Title;
  }

  public DataField(x: string): GridColumn {
    this._DataField = x;
    return this;
  }

  public getDataField(): string {
    return this._DataField;
  }

  public Type(x: GridColumnType): GridColumn {
    this._Type = x;
    if (
      x.getTableSpecialType() == GRID_DATA_TYPE.BUTTONS ||
      x.getTableSpecialType() == GRID_DATA_TYPE.ACTIONS
    )
      this.GroupingEnabled(false);
    return this;
  }

  public getType(): GRID_DATA_TYPE {
    return this._Type.getTableSpecialType();
  }

  public getTypeSettings(): GridColumnType {
    return this._Type;
  }

  public getFilter(): GRID_DATA_TYPE {
    return this._Filter.getTableSpecialFilter();
  }

  public getFilterSettings(): GridColumnFilter {
    return this._Filter;
  }

  public Editor(x: GridColumnEditor | boolean): GridColumn {
    if (typeof x === 'boolean') this._Editor = new GridTextboxEditor().Show(x);
    else {
      if (stringIsEmpty(x.getLabel())) x.Label(this.getTitle()); // if no special label for editor provided then use column title as label
      this._Editor = x;
    }

    return this;
  }

  public getEditor(): GRID_DATA_TYPE {
    return this._Editor.getTableSpecialEditor();
  }

  public getEditorSettings(): GridColumnEditor {
    return this._Editor;
  }

  public Filter(x: GridColumnFilter | boolean): GridColumn {
    if (typeof x === 'boolean') this._Filter = new GridTextboxFilter().Show(x);
    else this._Filter = x;
    return this;
  }

  public Docked(x: boolean): GridColumn {
    this._Docked = x;
    // reset menu items
    this.setUpMenuItems();
    return this;
  }

  public getDocked(): boolean {
    return this._Docked;
  }

  public Sortable(x: boolean): GridColumn {
    this._Sortable = x;
    this.setUpMenuItems();
    return this;
  }

  public getSortable(): boolean {
    return this._Sortable;
  }

  public Width(x: string): GridColumn {
    this._Width = x;
    return this;
  }

  public getWidth(): string {
    return this._Width;
  }

  public Visible(x: boolean): GridColumn {
    this._Visible = x;
    return this;
  }

  public getVisible(): boolean {
    return this._Visible;
  }

  public Grouped(x: boolean): GridColumn {
    this._Grouped = x;
    // reset menu items
    this.setUpMenuItems();
    return this;
  }

  public getGrouped(): boolean {
    return this._Grouped;
  }

  public GroupingEnabled(enabled: boolean): GridColumn {
    this._GroupingEnabled = enabled;
    this.setUpMenuItems();

    return this;
  }

  public getGroupingEnabled(): boolean {
    return this._GroupingEnabled;
  }

  public ShowGroupCount(x: boolean): GridColumn {
    this._ShowGroupCount = x;
    // reset menu items
    this.setUpMenuItems();
    return this;
  }

  public getShowGroupCount(): boolean {
    return this._ShowGroupCount;
  }

  private setUpMenuItems(): void {
    var items: NbMenuItem[] = [];
    if (this._Sortable) {
      items.push(
        {
          title: 'gridSort',
          group: true,
        },
        {
          title: 'gridSortAsc',
          icon: 'arrow-upward-outline',
          badge:
            this._SortState == GRID_SORT.ASC
              ? { status: 'primary', dotMode: true }
              : undefined,
          data: {
            action: GRID_MENU_ACTION.SORT_ASC,
            column: this,
          },
        },
        {
          title: 'gridSortDesc',
          icon: 'arrow-downward-outline',
          badge:
            this._SortState == GRID_SORT.DESC
              ? { status: 'primary', dotMode: true }
              : undefined,
          data: {
            action: GRID_MENU_ACTION.SORT_DESC,
            column: this,
          },
        }
      );
    }

    if (this._GroupingEnabled) {
      items.push({
        title: 'gridGrouping',
        group: true,
      });

      if (this._Grouped) {
        items.push({
          title: 'gridUngroup',
          icon: 'square-outline',
          data: {
            action: GRID_MENU_ACTION.UNGROUP,
            column: this,
          },
        });
      } else {
        items.push({
          title: 'gridGroup',
          icon: 'layers-outline',
          data: {
            action: GRID_MENU_ACTION.GROUP,
            column: this,
          },
        });
      }

      if (this._ShowGroupCount) {
        items.push({
          title: 'gridGroupCount',
          icon: 'eye-outline',
          badge: this._Grouped
            ? { status: 'primary', dotMode: true }
            : undefined,
          data: {
            action: GRID_MENU_ACTION.HIDE_GROUP_COUNT,
            column: this,
          },
        });
      } else {
        items.push({
          title: 'gridGroupCount',
          icon: 'eye-off-outline',
          data: {
            action: GRID_MENU_ACTION.SHOW_GROUP_COUNT,
            column: this,
          },
        });
      }
    }

    items.push({
      title: 'gridOther',
      group: true,
    });

    if (this._Docked) {
      items.push({
        title: 'gridUndock',
        icon: 'unlock-outline',
        data: {
          action: GRID_MENU_ACTION.UNDOCK,
          column: this,
        },
      });
    } else {
      items.push({
        title: 'gridDock',
        icon: 'lock-outline',
        data: {
          action: GRID_MENU_ACTION.DOCK,
          column: this,
        },
      });
    }

    this._ContextMenuItems = items;
  }

  public setSortState(state: GRID_SORT): void {
    if (state == this._SortState) this._SortState = GRID_SORT.NONE;
    else this._SortState = state;
    this.setUpMenuItems();
  }

  public getContextMenuId(): string {
    return this._ContextMenuId;
  }

  public getContextMenuItems(): NbMenuItem[] {
    return this._ContextMenuItems;
  }

  public getSortState(): GRID_SORT {
    return this._SortState;
  }

  public getId(): string {
    return this._Id;
  }

  public getExport(): boolean {
    return this._Export;
  }

  public Export(x: boolean): GridColumn {
    this._Export = x;
    return this;
  }
}
