import { Injectable } from '@angular/core';
import { GridColumn } from '../models/grid-column.model';
import { GRID_DATA_TYPE } from '../resources/mode-enums';
import { formatDate } from '@angular/common';

@Injectable({
  providedIn: 'root',
})
export class GridGroupService {
  public static groupData(column: GridColumn, data: any[]): any[] {
    var result = data.reduce(function (r, a) {
      var key = formatKeyByColumnType(column, a);

      r[key] = r[key] || [];
      r[key].push(a);
      return r;
    }, Object.create(null));

    var data = [];

    Object.keys(result).forEach((key: string, index: number) => {
      var elements = result[key];
      var groupName = generateGroupName(column, key);

      data.push({
        _GroupName: groupName,
        _GroupRow: true,
        _GroupCount: elements.length,
        _GroupExpanded: true,
        _GroupFirstElement: elements[0],
        _GroupId: index + 1,
      });

      data.push(...elements);
    });

    return data;
  }

  public static ungroupData(data: any[]): any[] {
    var ungrouped: any[] = [];
    ungrouped = data.filter((x: any) => !Object.keys(x).includes('_GroupRow'));

    return ungrouped;
  }
}

function formatKeyByColumnType(column: GridColumn, value: any): string {
  switch (column.getType()) {
    case GRID_DATA_TYPE.DATE:
      var key = formatDate(
        new Date(value[column.getDataField()]),
        column.getTypeSettings().getFormat(),
        'en-US'
      );

      return key;

    case GRID_DATA_TYPE.DATERANGE:
      var key =
        formatDate(
          new Date(value[column.getDataField()].start),
          column.getTypeSettings().getFormat(),
          'en-US'
        ) +
        ' - ' +
        formatDate(
          new Date(value[column.getDataField()].end),
          column.getTypeSettings().getFormat(),
          'en-US'
        );

      return key;

    case GRID_DATA_TYPE.LOOKUP:
      return value[column.getTypeSettings().getLookupColumn()];

    case GRID_DATA_TYPE.TAG:
      return value[column.getTypeSettings().getLookupColumn()];

    default:
      return value[column.getDataField()];
  }
}

function generateGroupName(column: GridColumn, key: string): string {
  var groupName: string = column.getTitle() + ': ';
  return groupName + key;
}
