import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { TranslationService } from '../resources/translation.service';
import { strings } from '../resources/strings';

@Component({
  selector: 'ngx-text-editor',
  templateUrl: './text-editor.component.html',
  styleUrls: ['./text-editor.component.scss'],
})
export class TextEditorComponent implements OnInit {
  constructor(private translationService: TranslationService) {}

  ngOnInit(): void {
    // check if translations are already loaded (from external app)
    if (!this.translationService.isTranslationsLoaded()) {
      this.translationService.setTranslations(strings);
    }
  }

  private _text: string = '';

  @Input() placeholder: string =
    this.translationService.translate('editorTypeText');

  @Input() set text(value: string) {
    this._text = value;
    this.textChange.emit(this._text);
  }
  get text(): string {
    return this._text;
  }

  @Output() textChange: EventEmitter<any> = new EventEmitter<any>();

  public config = {
    placeholder: this.placeholder,
    toolbar: [
      ['misc', ['codeview', 'undo', 'redo']],
      [
        'font',
        [
          'bold',
          'italic',
          'underline',
          'strikethrough',
          'superscript',
          'subscript',
          'clear',
        ],
      ],
      ['fontsize', ['fontsize']],
      ['para', ['style', 'ul', 'ol', 'paragraph', 'height']],
      ['insert', ['table', 'hr']],
    ],
    fontNames: ['Open Sans'],
  };
}
