import { Injectable } from '@angular/core';
import { IGridSort } from '../models/grid.model';
import { GRID_SORT, GRID_DATA_TYPE } from '../resources/mode-enums';
import { DatePipe } from '@angular/common';

@Injectable({
  providedIn: 'root',
})
export class GridSortService {
  public static sortData(data: any[], sort: IGridSort[]): any[] {
    var sorted: any[] = data;

    sort.forEach((element) => {
      switch (element.column.getType()) {
        case GRID_DATA_TYPE.DATE:
          sorted = sortDate(sorted, element);
          break;
        case GRID_DATA_TYPE.DATERANGE:
          sorted = sortDateRange(sorted, element);
          break;
        default:
          sorted = simpleSort(sorted, element);
          break;
      }
    });

    return sorted;
  }

  public static resetSort(data: any[]): any[] {
    return data.sort(function (a, b) {
      if (a._RowIndex < b._RowIndex) return -1;
      if (a._RowIndex > b._RowIndex) return 1;

      return 0;
    });
  }
}

function simpleSort(arrToSort: any[], element: IGridSort): any[] {
  arrToSort = arrToSort.sort(function (a, b) {
    if (a[element.column.getDataField()] < b[element.column.getDataField()])
      return -1;

    if (a[element.column.getDataField()] > b[element.column.getDataField()])
      return 1;

    return 0;
  });

  if (element.sortState === GRID_SORT.ASC) return arrToSort;
  else return arrToSort.reverse();
}

function sortDate(arrToSort: any[], element: IGridSort): any[] {
  arrToSort = arrToSort.sort(function (a, b) {
    let first = Number(
      new DatePipe('en-US').transform(
        a[element.column.getDataField()],
        'yyyyMMdd'
      )
    );
    let second = Number(
      new DatePipe('en-US').transform(
        b[element.column.getDataField()],
        'yyyyMMdd'
      )
    );

    if (first < second) return -1;
    if (first > second) return 1;

    return 0;
  });

  if (element.sortState === GRID_SORT.ASC) return arrToSort;
  else return arrToSort.reverse();
}

function sortDateRange(arrToSort: any[], element: IGridSort): any[] {
  arrToSort = arrToSort.sort(function (a, b) {
    let first = Number(
      new DatePipe('en-US').transform(
        a[element.column.getDataField()].start,
        'yyyyMMdd'
      )
    );
    let second = Number(
      new DatePipe('en-US').transform(
        b[element.column.getDataField()].start,
        'yyyyMMdd'
      )
    );

    if (first < second) return -1;
    if (first > second) return 1;

    return 0;
  });

  if (element.sortState === GRID_SORT.ASC) return arrToSort;
  else return arrToSort.reverse();
}
