import { NbComponentShape, NbComponentSize } from '@nebular/theme';
import { makeId } from '../functions/functions';
import { GRID_BUTTON_TYPE } from '../resources/mode-enums';

export class GridButtonType {
  private _Type: GRID_BUTTON_TYPE = GRID_BUTTON_TYPE.OTHER;
  private _Id: string = makeId(20);
  private _Status: string = 'basic';
  private _Hero: boolean = false;
  private _Ghost: boolean = true;
  private _Filled: boolean = false;
  private _Outlined: boolean = false;
  private _Disabled: boolean = false;
  private _Text: string = '';
  private _Icon: string = '';
  private _Tooltip: string = '';
  private _Shape: NbComponentShape = 'round';
  private _Size: NbComponentSize = 'medium';
  private _Class: string = '';
  private _TooltipDisabled: boolean = false;

  constructor() {}

  public Type(x: GRID_BUTTON_TYPE): GridButtonType {
    this._Type = x;
    return this;
  }

  public getType(): GRID_BUTTON_TYPE {
    return this._Type;
  }

  public Id(x: string): GridButtonType {
    this._Id = x;
    return this;
  }

  public getId(): string {
    return this._Id;
  }

  public Status(x: string): GridButtonType {
    this._Status = x;
    return this;
  }

  public getStatus(): string {
    return this._Status;
  }

  public Hero(x: boolean): GridButtonType {
    this._Hero = x;
    return this;
  }

  public getHero(): boolean {
    return this._Hero;
  }

  public Ghost(x: boolean): GridButtonType {
    this._Ghost = x;
    return this;
  }

  public getGhost(): boolean {
    return this._Ghost;
  }

  public Filled(x: boolean): GridButtonType {
    this._Filled = x;
    return this;
  }

  public getFilled(): boolean {
    return this._Filled;
  }

  public Outlined(x: boolean): GridButtonType {
    this._Outlined = x;
    return this;
  }

  public getOutlined(): boolean {
    return this._Outlined;
  }

  public Disabled(x: boolean): GridButtonType {
    this._Disabled = x;
    return this;
  }

  public getDisabled(): boolean {
    return this._Disabled;
  }

  public Text(x: string): GridButtonType {
    this._Text = x;
    return this;
  }

  public getText(): string {
    return this._Text;
  }

  public Icon(x: string): GridButtonType {
    this._Icon = x;
    return this;
  }

  public getIcon(): string {
    return this._Icon;
  }

  public Tooltip(x: string): GridButtonType {
    this._Tooltip = x;
    return this;
  }

  public getTooltip(): string {
    return this._Tooltip;
  }

  public Shape(x: NbComponentShape): GridButtonType {
    this._Shape = x;
    return this;
  }

  public getShape(): NbComponentShape {
    return this._Shape;
  }

  public Size(x: NbComponentSize): GridButtonType {
    this._Size = x;
    return this;
  }

  public getSize(): NbComponentSize {
    return this._Size;
  }

  public Class(x: string): GridButtonType {
    this._Class = x;
    return this;
  }

  public getClass(): string {
    return this._Class;
  }

  public TooltipDisabled(x: boolean): GridButtonType {
    this._TooltipDisabled = x;
    return this;
  }

  public getTooltipDisabled(): boolean {
    return this._TooltipDisabled;
  }
}
