import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  QueryList,
  ViewChild,
  ViewChildren,
} from '@angular/core';
import { GridColumn } from '../models/grid-column.model';
import { GRID_CONF } from '../resources/defaults';
import { strings } from '../resources/strings';
import {
  NbDialogService,
  NbMenuItem,
  NbMenuService,
  NbPosition,
  NbWindowService,
} from '@nebular/theme';
import {
  IGridAddEditPopupSettings,
  IGridCellButton,
  IGridGroup,
  IGridDeletePopupSettings,
  IGridExportDocumentSettings,
  IGridExportHeader,
  IGridFilter,
  IGridSelection,
  IGridSort,
  IGridEditedRow,
} from '../models/grid.model';
import { ColumnFilterComponent } from './column-filter/column-filter.component';
import { Subscription } from 'rxjs';
import { filter, map } from 'rxjs/operators';
import {
  GRID_ACTIONS_POSITION,
  GRID_BUTTON_TYPE,
  GRID_DATA_TYPE,
  GRID_MENU_ACTION,
  GRID_MODE,
  GRID_SORT,
  GRID_STATE,
} from '../resources/mode-enums';
import { GridFilterService } from './grid-filter.service';
import { GridSortService } from './grid-sort.service';
import { GridButtonsColumn } from '../models/grid-column-type.model';
import { GridActionsEditor } from '../models/grid-column-editor.model';
import { GridExport } from './export/grid-export.class';
import { GridPdfExportComponent } from './export/grid-pdf-export/grid-pdf-export.component';
import { GridExcelExportComponent } from './export/grid-excel-export/grid-excel-export.component';
import { PopupComponent } from './popup/popup.component';
import { GridPopup } from './popup/grid-popup.class';
import { DeletePopupComponent } from './delete-popup/delete-popup.component';
import { GridValidationService } from './grid-validation.service';
import { GridGroupService } from './grid-group.service';
import { GridButtonType } from '../models/grid-button-type.model';
import { makeId, pushToArrayAtIndexRange } from '../functions/functions';
import { TranslationService } from '../resources/translation.service';

@Component({
  selector: 'ngx-grid',
  templateUrl: './grid.component.html',
  styleUrls: ['./grid.component.scss'],
})
export class GridComponent implements OnInit, OnDestroy {
  constructor(
    private _menuService: NbMenuService,
    private _windowService: NbWindowService,
    private _dialogService: NbDialogService,
    private _translationService: TranslationService
  ) {}

  ngOnInit(): void {
    // check if translations are already loaded (from external app)
    if (!this._translationService.isTranslationsLoaded()) {
      this._translationService.setTranslations(strings);
    }

    // set columns indexes
    this.columns.map((x, index) => x.Index(index));

    // subscribe to column context menu click
    if (this.columnOptionsEnabled) this.initializeColumnsContextMenus();

    // if edit or delete enabled initialize actions column
    if (this.editEnabled || this.deleteEnabled) this.initializeActionsColumn();

    this.groupColspan = this.columns.length;
    if (this.selectionEnabled) this.groupColspan++;
  }

  ngOnDestroy(): void {
    this._subs.forEach((element) => {
      element.unsubscribe();
    });
  }

  // -------------------------------------------------- VIEW CHILDREN ----------------------------------------------------

  @ViewChildren(ColumnFilterComponent)
  _filtersChildren: QueryList<ColumnFilterComponent> = new QueryList();

  // ------------------------------------------------- VIEW CHILD --------------------------------------------------------

  @ViewChild(GridPdfExportComponent)
  _exportPDFComponent!: GridPdfExportComponent; // export PDF component instance
  @ViewChild(GridExcelExportComponent)
  _exportExcelComponent!: GridExcelExportComponent; // export Excel component instance

  // --------------------------------------------- INPUTS ----------------------------------------------------------------

  // ******************** DATA SOURCE SETTINGS ****************
  @Input() set data(value: any[]) {
    // reset row index if data source changed
    value = value.map((val: any, index) => {
      val._RowIndex = index;
      return val;
    });

    this._data = value;
    this.checkAnyGroupedColumns();
    this.refreshDataToRender(); // refresh data in table
    this._selectedRows = []; // reset selection if data source changed
  }
  get data(): any[] {
    return this._data;
  }

  // ******************** COLUMNS SETTINGS ****************
  @Input() public columns: GridColumn[] = []; // grid columns definition
  @Input() public columnOptionsEnabled: boolean = true; // shows or hides columns context menu

  // ******************** PAGER SETTINGS ****************
  @Input() public entriesPerPageEnabled: boolean = true; // shows or hides picker for entries per page
  @Input() public entriesPerPageOptions: number[] =
    GRID_CONF.entriesPerPageOptions; // array with options for entries per page selection if entriesPerPage enabled
  @Input() public pagerEnabled: boolean = true; // shows or hides table pager
  @Input() public defaultPerPageOption: number =
    this.entriesPerPageOptions?.length > 0
      ? this.entriesPerPageOptions[0]
      : GRID_CONF.defaultEntriesPerPage; // starting value of pager -> if not set then first from entriesPerPageOptions array option is used
  public entriesPerPageTooltip: string = this._translationService.translate(
    'gridEntriesPerPageTooltip'
  ); // tooltip to be shown on entries per pege selection hover -> empty string disables tooltip

  // ******************** EXPORT SETTINGS ****************
  @Input() public exportPdfEnabled: boolean = true; // shows or hides export PDF button
  public exportPdfTooltip: string = this._translationService.translate(
    'gridExportPdfTooltip'
  ); // tooltip to be shown on PDF export button hover -> empty string disables tooltip
  @Input() public exportExcelEnabled: boolean = true; // shows or hides export Excel button
  public exportExcelTooltip: string = this._translationService.translate(
    'gridExcelExportTooltip'
  ); // tooltip to be shown on Excel export button hover -> empty string disables tooltip
  @Input() public customExportFunction: boolean = false; // if set to true click on export buttons fires only click event but doesn't do default export
  @Input() public exportSettings: IGridExportDocumentSettings = {
    title: undefined, // title shown on first page
    subtitle: undefined, // subtitle shown on first page
    showOrdinalNumbers: true, // shows or hides row numbers
    ordNumColumnName: this._translationService.translate('gridTableOrdNumber'), // column name for row numbers
    docName: GRID_CONF.exportDocName, // export document name
    yesValueText: this._translationService
      .translate('gridTableYes')
      .toLowerCase(), // yes (true) value for boolean data
    noValueText: this._translationService
      .translate('gridTableNo')
      .toLowerCase(), // no (false) value for boolean data
  }; // setting object for built in export

  // ******************** SELECTION SETTINGS ****************
  @Input() public selectionMultiple: boolean = false; // if false then selection mode is single -> depends on selectionEnabled (if not enabled then no selection mode is required)
  @Input() public selectRowByClick: boolean = true; // enables or disables row selection by table row click
  @Input() public selectAllEnabled: boolean = false; // enables or disables select all checkbox
  public selectedRowsTitle: string =
    this._translationService.translate('gridSelectedRows'); // selected rows title when selection multiple enabled
  @Input() public selectedRowsTitleEnabled: boolean = true; // show or hides number of selected rows when selection multiple enabled
  @Input() public selectionEnabled: boolean = true; // enables/disables grid row selection

  // ******************** LOADING SETTINGS ****************
  @Input() public loadingEnabled: boolean = true; // enables or disables spinner loading on table
  public loadingMessage: string =
    this._translationService.translate('gridLoading'); // message to be shown on spinner loading if loading is enabled -> empty string disables message
  @Input() public loading: boolean = false; // for manual triggering of load spinner, works correctly if automatic loading is disabled (loadingEnabled=false)

  // ******************** FILTERS SETTINGS ****************
  @Input() public filtersEnabled: boolean = true; // show or hides filters row for all columns

  // ******************** ACTIONS SETTINGS ****************
  @Input() public actionsPosition: GRID_ACTIONS_POSITION =
    GRID_CONF.actionsPosition; // can be left or right
  public actionsColumnTitle: string =
    this._translationService.translate('gridActions'); // title for action column if actions are enabled
  @Input() public addEnabled: boolean = true; // shows or hides add button
  public addTooltip: string = this._translationService.translate('gridAddBtn'); // add button tooltip
  @Input() public editEnabled: boolean = true; // shows or hides edit buttons on rows
  @Input() public deleteEnabled: boolean = true; // shows or hides delete buttons on rows
  @Input() public addEditPopupSettings: IGridAddEditPopupSettings = {
    newRecordTitle: this._translationService.translate('gridNewRecord'), // popup title for adding new record
    editRecordTitle: this._translationService.translate('gridEditRecord'), // popup title for editing record
    saveBtnTitle: this._translationService.translate('gridSaveBtnText'), // popup save button text
    cancelBtnTitle: this._translationService.translate('gridCancelBtnText'), // popup cancel button text
    requiredTooltip: this._translationService.translate('gridRequiredTooltip'), // popup required field tooltip
    hasBacktrop: true, // shows or hides backrop on popup
    showFullScreenBtn: true, // shows or hides full screen button on popup
    showMaximizeBtn: true, // shows or hides maximize button on popup
    showMinimizeBtn: true, // shows or hides minimize button on popup
    closeOnBackdropClick: false, // enables or disables popup closing on backdrop click
    closeOnEscClick: false, // enables or disables popup closing on esc key press
  }; // setting object for add/edit popup if table mode popup
  @Input() public deletePopupSettings: IGridDeletePopupSettings = {
    useDefaultDialog: true, // if true default table dialog is used, else default delete event is fired
    title: this._translationService.translate('gridDeleteConfirmTitle'), // delete dialog title
    text: this._translationService.translate('gridDeleteConfirmText'), // delete dialog body text
    yesBtnText: this._translationService.translate('gridTableYes'), // yes (confirm) dialog button text
    noBtnText: this._translationService.translate('gridTableNo'), // no (cancel) dialog button text
    closeOnBackdropClick: true, // enables or disables dialog closing on backdrop click
    closeOnEsc: true, // enables or disables dialog closing on esc key press
  }; // setting object for delete dialog if table mode popup

  // ******************** GRID SETTINGS ****************
  @Input() public refreshEnabled: boolean = true; // shows or hides refresh table button
  public refreshTooltip: string =
    this._translationService.translate('gridRefreshTooltip'); // tooltip to be shown on Refresh button hover -> empty string disables tooltip
  @Input() public noDataMessage: string = this._translationService.translate('gridNoData'); // message to be displayed when there's no data in source
  @Input() public gridMode: GRID_MODE = GRID_MODE.INLINE; // grid insert and edit mode
  @Input() public rowHeight: number = 0; // grid row height in px - if 0 then auto height

  // --------------------------------------------- OUTPUTS -----------------------------------------------------------

  @Output() private entriesPerPageSelectionChanged = new EventEmitter<number>(); // fires when selected option of entries per page changed
  @Output() private selectionChanged = new EventEmitter<IGridSelection>(); // fires when selected row changed if selection is enabled
  @Output() private pageChanged = new EventEmitter<number>(); // fires when page changed
  @Output() private sourceFiltersReseted = new EventEmitter<boolean>(); // fires when reset button is clicked
  @Output() private sortChanged = new EventEmitter<IGridSort>(); // fires when sorting option changed
  @Output() private filterChanged = new EventEmitter<IGridFilter>(); // fires when sorting option changed
  @Output() private pdfExport = new EventEmitter<any>(); // fires when PDF export button is clicked
  @Output() private excelExport = new EventEmitter<any>(); // fires when Excel export button is clicked
  @Output() private createConfirm = new EventEmitter<IGridEditedRow>(); // fires if table mode inline or popup when save button is clicked on new record
  @Output() private editConfirm = new EventEmitter<IGridEditedRow>(); // fires if table mode inline or popup when save button is clicked on new record
  @Output() private deleteConfirm = new EventEmitter<IGridEditedRow>(); // fires if table mode inline or popup when save button is clicked on new record
  @Output() private actionBtnClick = new EventEmitter<IGridCellButton>(); // fires if grid action button is clicked
  @Output() private createStarted = new EventEmitter<boolean>(); // fires if table mode external when new record button is clicked
  @Output() private editStarted = new EventEmitter<any>(); // fires if table mode external when edit button on row is clicked
  @Output() private deleteStarted = new EventEmitter<any>(); // fires if table mode external when delete button on row is clicked
  @Output() private groupingChanged = new EventEmitter<IGridGroup>(); // fires when column grouping is changed

  // ------------------------------------------- PRIVATE FIELDS ------------------------------------------------------

  private _data: any;
  private _selectedRows: any[] = [];
  private _subs: Subscription[] = [];
  private _filters: IGridFilter[] = []; // all applied filters
  private _sort: IGridSort[] = []; // all applied sorting
  private _dockedColumns: GridColumn[] = []; // all docked columns
  private _rowInEditingInlineData: any; // old row data for grid inline edit mode

  // ------------------------------------------- PUBLIC FIELDS -------------------------------------------------------

  public page: number = 1;
  public position = NbPosition;
  public sortStates = GRID_SORT;
  public dataToRender: any[] = []; // filtered and sorted data to be rendered in table
  public gridState: GRID_STATE = GRID_STATE.NONE; // current grid state
  public gridStates = GRID_STATE;
  public gridModes = GRID_MODE;
  public newRowData: any = {}; // new row data for grid inline edit mode
  public groupedColumn: GridColumn | null = null; // all grouped columns
  public groupColspan: number = 1;
  public id: string = makeId(30);

  // ------------------------------------------ PRIVATE METHODS -----------------------------------------------------

  /**
   *
   */
  private checkAnyGroupedColumns(): void {
    var column = this.columns.find((x: GridColumn) => x.getGrouped());
    if (column) this.groupedColumn = column;
  }

  /**
   *
   * @param row selected row to be edited
   */
  private startGridEdit(row: any): void {
    if (this.gridCanBeModified()) {
      this.editStarted.emit({ data: row });

      if (this.gridMode == GRID_MODE.POPUP) this.openAddEditPopup(row);
      else if (this.gridMode == GRID_MODE.INLINE) {
        this._rowInEditingInlineData = JSON.parse(JSON.stringify(row));
        row.mode = 'edit';
      }

      this.setGridState(GRID_STATE.EDIT);
    }
  }

  /**
   *
   * @param row row data to be deleted
   */
  private startGridDelete(row: any): void {
    if (this.gridCanBeModified()) {
      this.deleteStarted.emit({ data: row });
      // if use default delete dialog open popup, default dialog doesn't depend on grid mode
      if (this.deletePopupSettings.useDefaultDialog) this.openDeletePopup(row);

      this.setGridState(GRID_STATE.DELETE);
    }
  }

  /**
   * Initializes columns context menus and subscribes to clicks if column context menu is enabled
   */
  private initializeColumnsContextMenus(): void {
    this._subs.push(
      this._menuService
        .onItemClick()
        .pipe(
          filter(({ tag }) => {
            return tag?.startsWith('column-context-menu-' + this.id + '-');
          }),
          map(({ item }) => item)
        )
        .subscribe((item: NbMenuItem) => {
          this.onColumnContextMenuClick(item);
        })
    );
  }

  /**
   * Initializes grid column for actions if some of actions are enabled
   */
  private initializeActionsColumn(): void {
    var buttons: GridButtonType[] = [];

    if (this.editEnabled)
      buttons.push(
        new GridButtonType()
          .Type(GRID_BUTTON_TYPE.EDIT)
          .Icon('edit-outline')
          .Tooltip(this._translationService.translate('gridEditTooltip'))
      );

    if (this.deleteEnabled)
      buttons.push(
        new GridButtonType()
          .Type(GRID_BUTTON_TYPE.DELETE)
          .Icon('trash-outline')
          .Tooltip(this._translationService.translate('gridDeleteTooltip'))
      );

    var actionColumn: GridColumn = new GridColumn()
      .Title(this.actionsColumnTitle)
      .Type(
        new GridButtonsColumn()
          .Editable(this.editEnabled)
          .Removable(this.deleteEnabled)
          .Buttons(buttons)
      )
      .Sortable(false)
      .Filter(false)
      .Export(false)
      .GroupingEnabled(false)
      .Width('120px')
      .Editor(
        new GridActionsEditor().Buttons([
          new GridButtonType()
            .Type(GRID_BUTTON_TYPE.SAVE)
            .Icon('checkmark-outline')
            .Tooltip(this._translationService.translate('gridSaveTooltip')),
          new GridButtonType()
            .Type(GRID_BUTTON_TYPE.CANCEL)
            .Icon('close-outline')
            .Tooltip(this._translationService.translate('gridCancelTooltip')),
        ])
      );

    // default action columns position is right, otherwise action column needs to be set in first place in columns array (so it could be rendered on table start)
    if (this.actionsPosition == GRID_ACTIONS_POSITION.RIGHT)
      this.columns.push(actionColumn);
    else this.columns.unshift(actionColumn);
  }

  /**
   * Performs action based on column context menu item that was clicked
   * @param item {NbMenuItem} object that is clicked
   */
  private onColumnContextMenuClick(item: NbMenuItem): void {
    switch (item.data.action) {
      case GRID_MENU_ACTION.DOCK:
        this.onColumnDockingChange(item.data.column, true);
        break;

      case GRID_MENU_ACTION.UNDOCK:
        this.onColumnDockingChange(item.data.column, false);
        break;

      case GRID_MENU_ACTION.SORT_ASC:
        this.onColumnSortChange(true, item.data.column);
        break;

      case GRID_MENU_ACTION.SORT_DESC:
        this.onColumnSortChange(false, item.data.column);
        break;

      case GRID_MENU_ACTION.GROUP:
        this.onColumnGroupingChange(item.data.column, true);
        break;

      case GRID_MENU_ACTION.UNGROUP:
        this.onColumnGroupingChange(item.data.column, false);
        break;

      case GRID_MENU_ACTION.SHOW_GROUP_COUNT:
        (item.data.column as GridColumn).ShowGroupCount(true);
        break;

      case GRID_MENU_ACTION.HIDE_GROUP_COUNT:
        (item.data.column as GridColumn).ShowGroupCount(false);
        break;
    }
  }

  /**
   * It saves selected column to _dockedColumns array and calculates docked columns positions in grid
   * @param column {GridColumn} instance that was selected to docking
   * @param dock {boolean} flag indicating whether dock or undock is performed
   */
  private onColumnDockingChange(column: GridColumn, dock: boolean): void {
    column.Docked(dock);

    if (dock) this._dockedColumns.push(column);
    else {
      var index = this._dockedColumns.findIndex(
        (x) => x.getId() == column.getId()
      );
      this._dockedColumns.splice(index, 1);
    }

    // sort docked columns by index so left position can be calculated correctly
    this._dockedColumns.sort((a, b) => a.getIndex() - b.getIndex());
  }

  /**
   * Refreshes rendered data by applied filtering, sorting and grouping columns
   */
  private refreshDataToRender(): void {
    var filteredData = GridFilterService.filterData(this._filters, this.data); // filter grid data by all set filters
    // sort filtered data
    if (this._sort.length > 0)
      var sortedData = GridSortService.sortData(filteredData, this._sort);
    else var sortedData = GridSortService.resetSort(filteredData);

    // group sorted and filtered data
    if (this.groupedColumn)
      this.dataToRender = GridGroupService.groupData(
        this.groupedColumn,
        sortedData
      );
    else this.dataToRender = sortedData;
  }

  /**
   * It groups data based on selected column, only one column can be grouped at a time
   * @param column {GridColumn} instance that is selected for grouping
   * @param group {boolean} flag indicating whether grouping or ungrouping is performed
   */
  private onColumnGroupingChange(column: GridColumn, group: boolean): void {
    if (group) {
      // check already grouped --> ungroup it first
      if (this.groupedColumn) this.groupedColumn.Grouped(false);
      this.groupedColumn = column;
    } else this.groupedColumn = null;

    column.Grouped(group);
    this.refreshDataToRender();
    this.groupingChanged.emit({ column: column, grouped: group });
  }

  /**
   * It sorts data based on selected column and direction
   * @param asc {boolean} flag indicating whether ascending or descending sorting is performed
   * @param column {GridColumn} instance that is selected for sorting
   */
  private onColumnSortChange(asc: boolean, column: GridColumn): void {
    column.setSortState(asc ? GRID_SORT.ASC : GRID_SORT.DESC);

    // try to find index of column for sorting, if it exists just update sort state
    var columnIndex = this._sort.findIndex(
      (sort) => sort.column.getId() == column.getId()
    );

    var sortState = column.getSortState();

    if (sortState != GRID_SORT.NONE) {
      if (columnIndex > -1) this._sort[columnIndex].sortState = sortState;
      // if column sorting already applied, then only change its sort state
      else this._sort.push({ sortState: sortState, column: column }); // otherwise add column sorting to sorts
    } else this._sort.splice(columnIndex, 1); // if sorting reseted for column --> delete column from sorts

    this.refreshDataToRender();
    this.sortChanged.emit({ column: column, sortState: column.getSortState() });
  }

  /**
   * It opens add or edit grid popup
   * @param row row data to be edited, if undefined then add new action is performed
   */
  private openAddEditPopup(row: any = undefined): void {
    this._subs.push(
      this._windowService
        .open(
          PopupComponent,
          GridPopup.getPopupConfiguration(
            row ? false : true,
            row
              ? this.addEditPopupSettings.editRecordTitle
              : this.addEditPopupSettings.newRecordTitle,
            this.columns,
            row,
            this.addEditPopupSettings.saveBtnTitle,
            this.addEditPopupSettings.cancelBtnTitle,
            this.addEditPopupSettings.showMinimizeBtn,
            this.addEditPopupSettings.showMaximizeBtn,
            this.addEditPopupSettings.showFullScreenBtn,
            this.addEditPopupSettings.hasBacktrop,
            this.addEditPopupSettings.closeOnBackdropClick,
            this.addEditPopupSettings.closeOnEscClick,
            this.addEditPopupSettings.requiredTooltip
          )
        )
        .onClose.subscribe((data: IGridEditedRow | boolean) => {
          if (typeof data !== 'boolean' && data !== undefined) {
            if (row) this.editConfirm.emit(data);
            else this.createConfirm.emit(data);
          }
          this.resetGridState();
        })
    );
  }

  /**
   * Opens delete row confirmation dialog
   * @param row Row data to be deleted
   */
  private openDeletePopup(row: any): void {
    this._subs.push(
      this._dialogService
        .open(
          DeletePopupComponent,
          GridPopup.getDeletePopupConfiguration(this.deletePopupSettings)
        )
        .onClose.subscribe((data: boolean) => {
          if (data) this.deleteConfirm.emit({ data: row, newData: row });
          this.resetGridState();
        })
    );
  }

  /**
   * Sets new grid state, sets state for all modes except external 'couse in external mode state cannot be changed back to none
   * @param state GRID_STATE to be set
   */
  private setGridState(state: GRID_STATE): void {
    if (this.gridMode == GRID_MODE.POPUP || this.gridMode == GRID_MODE.INLINE)
      this.gridState = state;
    else this.resetGridState();
  }

  /**
   * Resets grid state to none
   */
  private resetGridState(): void {
    this.gridState = GRID_STATE.NONE;
  }

  /**
   *
   * @returns Boolean indicating whether the grid can be modified
   */
  private gridCanBeModified(): boolean {
    return this.gridState == GRID_STATE.NONE;
  }

  /**
   *
   * @param row row data to be saved, if null then save new row data
   */
  private saveInlineGridForm(row: any = null): void {
    var formIsValid = GridValidationService.validate(
      this.columns,
      row ?? this.newRowData
    );

    // save if form is valid
    if (formIsValid) {
      if (!row) this.createConfirm.emit(this.newRowData);
      else {
        this.editConfirm.emit({
          data: this._rowInEditingInlineData,
          newData: row,
        });

        row.mode = '';
      }

      this._rowInEditingInlineData = {};
      this.resetGridState();
    }
  }

  private scrollGridToTop(): void {
    var list = document
      .getElementById(this.id)
      ?.getElementsByClassName('ngx-grid-table');
    if (list && list.length > 0) list[0].scrollTop = 0;
  }

  // ----------------------------------------- PUBLIC METHODS -------------------------------------------------------

  /**
   *
   * @returns any[] array of selected rows
   */
  public getSelectedRows(): any[] {
    return this._selectedRows;
  }

  /**
   * Starts grid loading
   */
  public startLoading(): void {
    this.loading = true;
  }

  /**
   * Stops grid loading
   */
  public stopLoading(): void {
    this.loading = false;
  }

  /**
   * Toggle grid loading
   */
  public toggleLoading(): void {
    this.loading = !this.loading;
  }

  /***
   * Selects specific rows by provided key
   * @param key String key on which to select
   * @param rows Array of rows to select, if no array is provided then it assumes single row selected
   */
  public selectRows(rows: any, key: string): void {
    if (!Array.isArray(rows)) rows = [rows];

    rows.forEach((element: any) => {
      var row = this._data.find((x: any) => x[key] == element);
      if (row) {
        row.selected = true;
        this.onSelectionCheckboxClick(row, true);
      }
    });
  }

  /**
   * Resets grid selection
   */
  public unselectAll() {
    this._selectedRows = [];
    this._data.map((x: any) => (x.selected = false));
  }

  // ------------------------------------------ DOM LISTENERS -------------------------------------------------------

  /**
   *
   * @param entriesPerPage Number of entries per page
   */
  public onSelectedChangePagerPerPage(entriesPerPage: number): void {
    this.page = 1; // reset page to start
    this.entriesPerPageSelectionChanged.emit(entriesPerPage);
    this.onPageChanged();
  }

  /**
   *
   * @param row Clicked row data
   * @param selected Boolean flag indicating whether row is selected or not
   */
  public onSelectionCheckboxClick(row: any, selected: boolean): void {
    // if single selection first deselect current selected row and reset selectedRows array, then push new selected row
    if (!this.selectionMultiple) {
      this._selectedRows.map((row) => (row.selected = false));
      this._selectedRows = [];
      if (selected) this._selectedRows.push(row);
    } else {
      if (selected) this._selectedRows.push(row);
      else {
        row.selected = false;
        this._selectedRows = this._selectedRows.filter(
          (row) => row.selected == true
        );
      }
    }

    // emit selection event
    this.selectionChanged.emit({
      selectedRows: this._selectedRows,
      currentRowEmitting: row,
      checked: selected,
    });
  }

  /**
   * Performs selection if selection by click is enabled and if clicked column is not button column (if buttons then button click event is fired)
   * if grid state is edit or insert it prevents selection
   * @param row Row data that was clicked
   * @param column Cell column that was clicked
   */
  public onRowDataClick(row: any, column: GridColumn): void {
    if (this.selectionEnabled) {
      if (
        this.selectRowByClick &&
        column.getType() != GRID_DATA_TYPE.BUTTONS &&
        this.gridCanBeModified()
      ) {
        row.selected = !row.selected;
        this.onSelectionCheckboxClick(row, row.selected);
      }
    }
  }

  /**
   *
   * @param selected Boolean flag indicating whether select all is performed or deselect all
   */
  public onSelectAllCheckedChange(selected: boolean): void {
    if (selected) {
      this.data.map((row) => (row.selected = true));
      this._selectedRows = this.data;
    } else {
      this._selectedRows.map((x) => (x.selected = false));
      this._selectedRows = [];
    }

    // emit selection event
    this.selectionChanged.emit({
      selectedRows: this._selectedRows,
      currentRowEmitting: {},
      checked: selected,
    });
  }

  /**
   * Emits pageChanged event
   */
  public onPageChanged(): void {
    this.scrollGridToTop();
    this.pageChanged.emit(this.page);
  }

  /**
   * Resets all filtering, sorting, grouping, selection and paging to default
   */
  public onClickResetFilters(): void {
    // deselect all rows
    this.onSelectAllCheckedChange(false);

    // reset pageing to first page
    this.page = 1;

    // reset all set filters
    if (this._filtersChildren.length > 0) {
      this._filtersChildren.forEach((element) => {
        element.resetFilter();
      });
    }
    this._filters = [];

    // reset all set sorting
    this._sort = [];
    this.columns.map((column) => column.setSortState(GRID_SORT.NONE));

    // reset grouping
    this.groupedColumn?.Grouped(false);
    this.groupedColumn = null;

    // refresh rendered data
    this.refreshDataToRender();

    // scroll grid
    this.scrollGridToTop();

    // emit grid filter reset event
    this.sourceFiltersReseted.emit(true);
  }

  /**
   *
   * @param selectedFilter Changed filter
   */
  public onGridFilterChange(selectedFilter: IGridFilter): void {
    var columnIndex = this._filters.findIndex(
      (filter) => filter.column.getId() == selectedFilter.column.getId()
    ); // check if column is already filtered

    const filterNotReseted =
      (selectedFilter.filterValue != '' &&
        selectedFilter.filterValue != null &&
        selectedFilter.filterValue != undefined) ||
      selectedFilter.filterValue == false; // if filter value is cleared then treat it as filter reset --> here we check if there is any value in filter

    if (filterNotReseted) {
      if (columnIndex > -1)
        this._filters[columnIndex].filterValue = selectedFilter.filterValue;
      // if column already filtered then just alter its filter value
      else this._filters.push(selectedFilter); // otherwise push new filter
    } else this._filters.splice(columnIndex, 1); // if empty filter value then remove column from filtering

    this.refreshDataToRender();

    this.filterChanged.emit(selectedFilter);
  }

  /**
   *
   * @param column Selected column to be sorted
   */
  public onSortButtonClick(column: GridColumn) {
    this.onColumnSortChange(
      column.getSortState() == GRID_SORT.ASC ? false : true,
      column
    );
  }

  /**
   *
   * @param selectedButton Action button that was clicked
   */
  public onActionButtonClick(selectedButton: IGridCellButton): void {
    switch (selectedButton.button.getType()) {
      case GRID_BUTTON_TYPE.EDIT:
        this.startGridEdit(selectedButton.row);
        break;

      case GRID_BUTTON_TYPE.DELETE:
        this.startGridDelete(selectedButton.row);
        break;

      case GRID_BUTTON_TYPE.OTHER:
        this.actionBtnClick.emit(selectedButton);
        break;
    }
  }

  public addNewClick(): void {
    if (this.gridCanBeModified()) {
      this.newRowData = {}; // rest new row data
      this.createStarted.emit(true);
      if (this.gridMode == GRID_MODE.POPUP) this.openAddEditPopup();
      this.setGridState(GRID_STATE.INSERT);
    }
  }

  /*
    Fires pdfExport output event if customExportFunction is enabled.
    If custumExportFunction is disabled initializes built in PDF export functionality.
  */
  public exportPdfBtnClick(): void {
    if (this.customExportFunction) this.pdfExport.emit(true);
    else {
      var dataToExport = GridGroupService.ungroupData(this.dataToRender);
      if (this.loadingEnabled) this.loading = true;
      if (dataToExport?.length > 0) {
        var headers: IGridExportHeader[] =
          GridExport.configureIGridExportHeaders(this.columns);
        this._exportPDFComponent.exportPdf(dataToExport, headers);
        if (this.loadingEnabled) this.loading = false;
      } else {
        if (this.loadingEnabled) this.loading = false;
      }
    }
  }

  /**
   * Fires excelExport output event if customExportFunction is enabled.
   * If custumExportFunction is disabled initializes built in Excel export functionality.
   */
  public exportExcelBtnClick(): void {
    if (this.customExportFunction) this.excelExport.emit(true);
    else {
      var dataToExport = GridGroupService.ungroupData(this.dataToRender);
      if (this.loadingEnabled) this.loading = true;
      if (dataToExport?.length > 0) {
        var headers: IGridExportHeader[] =
          GridExport.configureIGridExportHeaders(this.columns);
        this._exportExcelComponent.exportExcel(dataToExport, headers);
        if (this.loadingEnabled) this.loading = false;
      } else {
        if (this.loadingEnabled) this.loading = false;
      }
    }
  }

  /**
   * Calculates left column position in pixels for every docked column so it can stay sticky on horizontal scrolling
   * @returns {number} left column position for docked column, or null if column is not docked
   */
  public calculateLeftPosition(column: GridColumn): any {
    if (column.getDocked()) {
      let leftPosition = 0;
      var index = this._dockedColumns.findIndex(
        (x) => x.getId() == column.getId()
      );

      for (let i = 0; i < index; i++) {
        const element: HTMLElement | null = document.getElementById(
          this._dockedColumns[i].getId()
        );

        if (element) {
          const width: number = element.offsetWidth;
          leftPosition += width;
        }
      }

      return leftPosition;
    }

    return null;
  }

  /**
   * Grid toolbar is visible if addEnabled (add button is visible), selectionMultiple and selectionRowsTitle is enabled and something is selected
   * @returns {boolean} flag indicating whether the grid toolbar is visible
   */
  public getGridToolbarVisibility(): boolean {
    return (
      this.addEnabled ||
      (this.selectionMultiple &&
        this.getSelectedRows().length > 0 &&
        this.selectedRowsTitleEnabled)
    );
  }

  /**
   * Footer is visible if any of buttons in footer is visible, otherwise grid height is full container height
   * @returns {boolean} flag indicating whether the footer is visible
   */
  public getGridFooterVisibility(): boolean {
    return (
      this.refreshEnabled ||
      this.exportPdfEnabled ||
      this.exportExcelEnabled ||
      this.entriesPerPageEnabled ||
      this.pagerEnabled
    );
  }

  /**
   *
   * @param btn GridButton that is clicked
   * @param row Selected row data
   */
  public inlineEditCellBtnClick(btn: GridButtonType, row: any = null) {
    switch (btn.getType()) {
      case GRID_BUTTON_TYPE.SAVE:
        this.saveInlineGridForm(row);
        break;

      case GRID_BUTTON_TYPE.CANCEL:
        if (row) row.mode = '';
        this.resetGridState();
        break;

      case GRID_BUTTON_TYPE.OTHER:
        this.actionBtnClick.emit({ row: row, button: btn });
        break;
    }
  }

  /**
   *
   * @param column Selected header column to apply class list
   * @returns {string} List of column classes
   */
  public getColumnHeaderClassList(column: GridColumn): string {
    var classList = 'sticky-th';
    if (column.getSortState() != GRID_SORT.NONE) classList += ' sorted';
    if (column.getDocked()) classList += ' docked docked-header';
    if (column.getGrouped()) classList += ' grouped';

    return classList;
  }

  /**
   *
   * @param column Selected column to ungroup
   */
  public onUngroupButtonClick(column: GridColumn) {
    this.onColumnGroupingChange(column, false);
  }

  public onGroupRowClick(row: any): void {
    row._GroupExpanded = !row._GroupExpanded;

    if (row._GroupExpanded) {
      // on expand insert collapsed row data into dataToRender
      pushToArrayAtIndexRange(
        this.dataToRender,
        row._GroupCollapsedElements,
        row._GroupFirstElementIndex
      );
      row._GroupCollapsedElements = null;
    } else {
      var firstRowIndex = this.dataToRender.findIndex(
        (x: any) => x._RowIndex === row._GroupFirstElement._RowIndex
      );
      // delete group rows from dataToRender
      if (firstRowIndex > -1) {
        row._GroupFirstElementIndex = firstRowIndex;
        row._GroupCollapsedElements = this.dataToRender.splice(
          firstRowIndex,
          row._GroupCount
        );
      }
    }
  }

  public onColumnContextMenuButtonClick(items: NbMenuItem[]): void {
    setTimeout(() => {
      var elements = document.getElementsByClassName(
        'ngx-grid-column-context-menu'
      );

      if (elements.length > 0) {
        var element = elements[0];

        element
          .closest('.cdk-overlay-container')
          ?.classList.add('ngx-grid-context-menu-cdk-overlay-container');

        // translate menu items title
        items.forEach((item) => {
          item.title = this._translationService.translate(item.title);
        });
      }
    }, 100);
  }
}
