import { NbComponentShape, NbTagAppearance } from '@nebular/theme';
import { GRID_DATA_TYPE } from '../resources/mode-enums';
import { GridButtonType } from './grid-button-type.model';

export abstract class GridColumnType {
  protected _Type: GRID_DATA_TYPE = GRID_DATA_TYPE.TEXT;
  protected _Format: string = 'dd.MM.yyyy.';
  protected _LookupColumn: string = '';
  protected _ColorColumn: string = '';
  protected _Appearance: NbTagAppearance = 'outline';
  protected _Shape: NbComponentShape = 'rectangle';
  protected _DisplayValue: boolean = true;
  protected _Editable: boolean = true;
  protected _Removable: boolean = true;
  protected _ButtonsFromDataField: string | boolean = false;
  protected _Buttons: GridButtonType[] = [];
  protected _IconColumn: string = '';
  protected _IsEvaIcon: boolean = false;

  constructor() {}

  public getTableSpecialType(): GRID_DATA_TYPE {
    return this._Type;
  }

  public getFormat(): string {
    return this._Format;
  }

  public getLookupColumn(): string {
    return this._LookupColumn;
  }

  public getColorColumn(): string {
    return this._ColorColumn;
  }

  public getAppearance(): NbTagAppearance {
    return this._Appearance;
  }

  public getShape(): NbComponentShape {
    return this._Shape;
  }

  public getDisplayValue(): boolean {
    return this._DisplayValue;
  }

  public getEditable(): boolean {
    return this._Editable;
  }

  public getRemovable(): boolean {
    return this._Removable;
  }

  public getButtonsFromDataField(): string | boolean {
    return this._ButtonsFromDataField;
  }

  public getButtons(): GridButtonType[] {
    return this._Buttons;
  }

  public getIconColumn(): string {
    return this._IconColumn;
  }

  public getIsEvaIcon(): boolean {
    return this._IsEvaIcon;
  }
}

export class GridNumberColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.NUMBER;
  }
}

export class GridTextColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.TEXT;
  }
}

export class GridDateColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.DATE;
  }

  public Format(x: string): GridDateColumn {
    this._Format = x;
    return this;
  }
}

export class GridToggleColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.TOGGLE;
  }
}

export class GridCheckboxColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.CHECKBOX;
  }
}

export class GridTagColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.TAG;
    this._Appearance = 'outline';
    this._Shape = 'rectangle';
  }

  public LookupColumn(x: string): GridTagColumn {
    this._LookupColumn = x;
    return this;
  }

  public ColorColumn(x: string): GridTagColumn {
    this._ColorColumn = x;
    return this;
  }

  public IconColumn(x: string): GridTagColumn {
    this._IconColumn = x;
    return this;
  }

  public Appearance(x: NbTagAppearance): GridTagColumn {
    this._Appearance = x;
    return this;
  }

  public Shape(x: NbComponentShape): GridTagColumn {
    this._Shape = x;
    return this;
  }

  public IsEvaIcon(x: boolean): GridTagColumn {
    this._IsEvaIcon = x;
    return this;
  }
}

export class GridProgressbarColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.PROGRESSBAR;
  }

  public ColorColumn(x: string): GridProgressbarColumn {
    this._ColorColumn = x;
    return this;
  }

  public DisplayValue(x: boolean): GridProgressbarColumn {
    this._DisplayValue = x;
    return this;
  }
}

export class GridDateRangeColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.DATERANGE;
  }

  public Format(x: string): GridDateRangeColumn {
    this._Format = x;
    return this;
  }
}

export class GridLookupColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.LOOKUP;
  }

  public LookupColumn(x: string): GridLookupColumn {
    this._LookupColumn = x;
    return this;
  }
}

export class GridButtonsColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.BUTTONS;
  }

  public Editable(x: boolean): GridButtonsColumn {
    this._Editable = x;
    return this;
  }

  public Removable(x: boolean): GridButtonsColumn {
    this._Removable = x;
    return this;
  }

  public ButtonsFromDataField(x: string | boolean): GridButtonsColumn {
    this._ButtonsFromDataField = x;
    return this;
  }

  public Buttons(x: GridButtonType[]): GridButtonsColumn {
    this._Buttons = x;
    return this;
  }
}

export class GridColorpickerColumn extends GridColumnType {
  constructor() {
    super();
    this._Type = GRID_DATA_TYPE.COLOR;
  }
}
