import { Component, Input, OnInit } from '@angular/core';
import * as XLSX from 'xlsx';
import { GRID_DATA_TYPE } from '../../../resources/mode-enums';
import { GridExport } from '../grid-export.class';
import {
  IGridExportDocumentSettings,
  IGridExportHeader,
} from '../../../models/grid.model';

@Component({
  selector: 'ngx-grid-excel-export',
  templateUrl: './grid-excel-export.component.html',
  styleUrls: ['./grid-excel-export.component.scss'],
})
export class GridExcelExportComponent implements OnInit {
  // ----------------------------------------------------- PRIVATE FIELDS ----------------------------------------------------------

  // ----------------------------------------------------- PUBLIC FIELDS -----------------------------------------------------------

  public headers: IGridExportHeader[] = []; // table headers
  public data: any[] = []; // data to export
  public specialTypes = GRID_DATA_TYPE; // specialTypes enum

  // ----------------------------------------------------- INPUTS ------------------------------------------------------------------

  @Input() settings!: IGridExportDocumentSettings; // export settings

  // ----------------------------------------------------- OUTPUTS -----------------------------------------------------------------

  // ----------------------------------------------------- COMPONENT CONSTRUCTION --------------------------------------------------

  constructor() {}

  ngOnInit(): void {}

  // ----------------------------------------------------- PRIVATE METHODS ---------------------------------------------------------

  // ----------------------------------------------------- PUBLIC METHODS ----------------------------------------------------------

  /*
    Exports and downloads provided data in xlsx format.
  */
  public exportExcel(data: any, headers: IGridExportHeader[]): void {
    this.headers = headers;
    this.data = data;

    //await for HTML elements to render
    setTimeout(() => {
      let element = document.getElementById('excel-table');
      const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(element);
      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
      XLSX.writeFile(wb, this.settings.docName + '.xlsx');
    }, 100);
  }

  public getFilename(item: any, header: IGridExportHeader): string {
    return GridExport.getFilename(item, header);
  }

  // ----------------------------------------------------- DOM LISTENERS -----------------------------------------------------------
}
