import { Component, OnInit } from '@angular/core';
import { NbDialogRef } from '@nebular/theme';
import { IGridDeletePopupSettings } from '../../models/grid.model';

@Component({
  selector: 'ngx-delete-popup',
  templateUrl: './delete-popup.component.html',
  styleUrls: ['./delete-popup.component.scss'],
})
export class DeletePopupComponent implements OnInit {
  // ----------------------------------------------------- PRIVATE FIELDS ----------------------------------------------------------

  // ----------------------------------------------------- PUBLIC FIELDS -----------------------------------------------------------

  public settings: IGridDeletePopupSettings = {
    // delete popup settings
    useDefaultDialog: true,
    title: '',
    text: '',
    closeOnBackdropClick: true,
    closeOnEsc: true,
  };

  // ----------------------------------------------------- INPUTS ------------------------------------------------------------------

  // ----------------------------------------------------- OUTPUTS -----------------------------------------------------------------

  // ----------------------------------------------------- COMPONENT CONSTRUCTION --------------------------------------------------

  constructor(private ref: NbDialogRef<DeletePopupComponent>) {}

  ngOnInit(): void {}

  // ----------------------------------------------------- PRIVATE METHODS ---------------------------------------------------------

  // ----------------------------------------------------- PUBLIC METHODS ----------------------------------------------------------

  // ----------------------------------------------------- DOM LISTENERS -----------------------------------------------------------

  public onNoClick(): void {
    this.ref.close(false);
  }

  public onYesClick(): void {
    this.ref.close(true);
  }
}
