import { HttpClient } from '@angular/common/http';
import {
  AfterViewInit,
  Component,
  OnDestroy,
  OnInit,
  TemplateRef,
  ViewChild,
} from '@angular/core';
import { NbButton, NbWindowRef, NbMenuItem } from '@nebular/theme';
import { Subscription } from 'rxjs';
import { GRID_EDITORS_CONF } from '../../resources/defaults';
import {
  FILE_MENU_CODES,
  GRID_DATA_TYPE,
  GRID_DATE_PICKER,
} from '../../resources/mode-enums';
import { GridColumn } from '../../models/grid-column.model';
import { GridValidationService } from '../grid-validation.service';
import { GridPopup } from './grid-popup.class';
import { IGridEditedRow, IGridPopupEditor } from '../../models/grid.model';
import { TranslationService } from '../../resources/translation.service';

@Component({
  selector: 'ngx-popup',
  templateUrl: './popup.component.html',
  styleUrls: ['./popup.component.scss'],
})
export class PopupComponent implements OnInit, AfterViewInit, OnDestroy {
  // ----------------------------------------------------- PRIVATE FIELDS ----------------------------------------------------------

  private uploadedFiles: File[] = []; // current uploaded files in filepicker editor
  private subscriptions: Subscription[] = [];

  // ----------------------------------------------------- PUBLIC FIELDS -----------------------------------------------------------

  public isNew: boolean = true; // indicates if new record option is active or edit record
  public columns: GridColumn[] = []; // smart table columns settings
  public data: any = null; // current data selected, if new record then null, if edit record then data from selected row
  public newData: any = {}; // object for new data provided in popup form
  public icon: string = ''; // popup window icon
  public title: string = ''; // popup window title
  public saveBtnText: string =
    this.translationService.translate('gridSaveBtnText'); // popup save button text
  public cancelBtnText: string =
    this.translationService.translate('gridCancelBtnText'); // popup cancel button text
  public requiredTooltip: string = this.translationService.translate(
    'gridRequiredTooltip'
  ); // tooltip for required field
  public editorDefaults = GRID_EDITORS_CONF; // default editor values
  public editorTypes = GRID_DATA_TYPE; // types of special editors supported
  public datePickerTypes = GRID_DATE_PICKER;
  public autocompleteValues = {};

  // ----------------------------------------------------- VIEW CHILD --------------------------------------------------------------

  @ViewChild('titleTemplate') titleTemplate!: TemplateRef<any>;
  @ViewChild('formSaveButton') saveButton!: NbButton;

  // ----------------------------------------------------- COMPONENT CONSTRUCTION --------------------------------------------------

  constructor(
    private ref: NbWindowRef,
    private http: HttpClient,
    private translationService: TranslationService
  ) {}

  ngOnInit(): void {
    if (!this.isNew) this.newData = JSON.parse(JSON.stringify(this.data));

    var selectEditors = this.columns.filter(
      (x) =>
        x.getEditor() == GRID_DATA_TYPE.SELECT ||
        x.getEditor() == GRID_DATA_TYPE.AUTOCOMPLETE
    );
    selectEditors.forEach((element) => {
      if (element.getEditorSettings().getServerDataSource() == true) {
        this.subscriptions.push(
          this.http
            .get(element.getEditorSettings().getServerEndpoint())
            .subscribe((data) => {
              (element as any)._Editor._DataSource = data;
            })
        );
      }
    });
  }

  ngAfterViewInit(): void {
    // set up of popup window special styles
    var windows = document.getElementsByClassName('popup-window');

    for (let index = 0; index < windows.length; index++) {
      const window = windows[index];
      window.children[0]?.classList?.add('popup-card');
      if (window.children[0].children.length >= 2)
        window.children[0].children[1].classList?.add('popup-card-body');
      var element = window.children[0].children[0].children;

      for (var i = 0; i < element.length; i++) {
        if (element[i].className == 'buttons') {
          for (let index = 0; index < element[i].children.length; index++) {
            const child = element[i].children[index];
            child.classList.remove('shape-rectangle');
            child.classList.add('shape-round');
          }

          element[i].lastElementChild?.classList.remove('appearance-ghost');
          element[i].lastElementChild?.classList.add('appearance-hero');
        }
      }
    }

    this.icon = this.isNew ? 'plus-circle-outline' : 'edit-outline';
    this.title = this.ref.config.title;
    this.ref.config.titleTemplate = this.titleTemplate;

    this.validatePopupForm();
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((element) => {
      element.unsubscribe();
    });
  }

  //------------------------------------------------------ PRIVATE METHODS ---------------------------------------------------------------

  //------------------------------------------------------ DOM LISTENERS -----------------------------------------------------------

  public openDatepicker(ref: HTMLInputElement): void {
    ref.focus();
  }

  public onClickCancel(): void {
    this.ref.close(false);
  }

  /*
    Configures newData object based on settings provided.
    Closes popup on save click and returns new data provided in popup form and old data if edit record mode.
  */
  public onClickSave(): void {
    var result: IGridEditedRow = {
      data: this.data,
      newData: this.newData,
    };

    this.ref.close(result);
  }

  public onDateChange(col: GridColumn, value: Date): void {}

  public onTimeChange(col: GridColumn, value: any): void {}

  public onRangeChange(col: GridColumn, value: any): void {}

  /*
    Checks editor min and max values if editor type is number.
  */
  public texboxOnInput(event: any, col: GridColumn): void {}

  /*
    Emits fileMenuItemClickEvent with data about menu item click and row data.
    If delete item clicked then pop newData files array.
  */
  public onFileMenuItemClick(editor: IGridPopupEditor, item: NbMenuItem): void {
    GridPopup.emitFileMenuItemClickEvent({
      menuItem: item,
      rowData: this.data,
    });

    if (item.data.code == FILE_MENU_CODES.DELETE) {
      if (editor.multiple && editor.fileSettings.listOfFiles) {
        this.newData[editor.id].splice(
          this.newData[editor.id].indexOf(item.data.file),
          1
        );
        editor.maxFiles =
          editor.maxFilesInitial - this.newData[editor.id].length;
      } else this.newData[editor.id] = undefined;
    }
  }

  public onFilepickerUpload(files: File[]): void {
    this.uploadedFiles = files;
    this.validatePopupForm();
  }

  public validatePopupForm(): void {
    var isValid: boolean = GridValidationService.validate(
      this.columns,
      this.newData
    );
    this.saveButton.disabled = !isValid;
  }

  public onKeyPress(column: GridColumn, event: any): boolean | null {
    if (column.getEditorSettings().getLettersDisabled())
      return event.charCode == 8 || event.charCode == 0
        ? null
        : event.charCode >= 48 && event.charCode <= 57;
    else return null;
  }
}
