import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';

@Component({
  selector: 'ngx-grid-toolbar',
  templateUrl: './grid-toolbar.component.html',
  styleUrls: ['./grid-toolbar.component.scss'],
})
export class GridToolbarComponent implements OnInit {
  constructor() {}

  ngOnInit(): void {}

  @Input() visible: boolean = true;
  @Input() selectedRowsTitleEnabled: boolean = true;
  @Input() selectionMultiple: boolean = false;
  @Input() selectedRows: number = 0;
  @Input() selectedRowsTitle: string = '';
  @Input() addEnabled: boolean = true;
  @Input() public addTooltip: string = ''; // add button tooltip

  @Output() addNewClicked = new EventEmitter();

  public addNewClick() {
    this.addNewClicked.emit();
  }
}
