import {
  Component,
  EventEmitter,
  HostListener,
  Input,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import { NbPopoverDirective, NbPosition } from '@nebular/theme';
import { makeId } from '../functions/functions';
import { SelectGridSelectionModel } from '../models/select-grid.model';
import { getError } from '../resources/error-codes';
import { SelectGridPopoverComponent } from './select-grid-popover/select-grid-popover.component';
import { GridColumn } from '../models/grid-column.model';
import { IGridSelection } from '../models/grid.model';
import { TranslationService } from '../resources/translation.service';
import { strings } from '../resources/strings';

@Component({
  selector: 'ngx-select-grid',
  templateUrl: './select-grid.component.html',
  styleUrls: ['./select-grid.component.scss'],
})
export class SelectGridComponent implements OnInit {
  private clickInsideComponent = false;

  @HostListener('click')
  clickInside() {
    this.clickInsideComponent = true;
  }

  @HostListener('document:click', ['$event'])
  clickout(event: any) {
    var popoverContent = document.getElementById(
      'grid-popover-content-' + this.id
    );

    if (
      !this.clickInsideComponent &&
      event.target.id != 'grid-popover-content-' + this.id &&
      !popoverContent?.contains(event.target)
    ) {
      this.popover.hide();
      this.gridSelectOpen = false;
    }
    this.clickInsideComponent = false;
  }

  // ------------------------------------------------------ PRIVATE FIELDS -----------------------------------------------------

  private selectedItems: any[] = []; // array of selected items/objects
  private error: boolean = false; // indicator of errors in config
  private _source: any[] = [];
  private _selected: any[] = [];

  // ------------------------------------------------------ VIEW CHILD --------------------------------------------------------

  @ViewChild(NbPopoverDirective) popover!: NbPopoverDirective;

  // ------------------------------------------------------ PUBLIC FIELDS ------------------------------------------------------

  public selectLabel: string = ''; // label to show in input field
  public id: string = 'select-grid-' + makeId(15); // unique component id
  public gridSelectOpen: boolean = false;
  public position = NbPosition.BOTTOM;
  public component = SelectGridPopoverComponent;
  public popoverContext: any = { selectGridId: this.id };
  public inputValue: string = '';

  // ------------------------------------------------------ INPUTS -------------------------------------------------------------

  @Input() public columns: GridColumn[] = []; // definition of columns for grid table
  @Input() public valueAttr: string = ''; // name of key attribute in data source
  @Input() public multiple: boolean = false; // enables/disables multiple selection mode
  @Input() public attributesForLabel: string[] = []; // names of attributes to show in input label for selected items
  @Input() set source(value: any[]) {
    this._source = value;
  }
  get source(): any[] {
    return this._source;
  }
  @Input() set selected(value: any[]) {
    this._selected = value;
    this.selectedChange.emit(this._selected);
    this.setInputValue();
  } // current selected keys
  get selected(): any[] {
    return this._selected;
  }
  @Output() selectedChange: EventEmitter<any> = new EventEmitter<any>();

  @Input() public disabled: boolean = false;
  @Input() public placeholder: string =
    this._translationService.translate('sgPlaceholder'); // input placeholder
  @Input() public searchEnabled: boolean = false; // enables/disables search option
  @Input() public customWidth: number = 0; // custom popover width

  // ------------------------------------------------------ OUTPUTS ------------------------------------------------------------

  @Output() public onSelectionChanged: EventEmitter<SelectGridSelectionModel> =
    new EventEmitter<SelectGridSelectionModel>(); // fires when selected items changed

  // ------------------------------------------------------ COMPONENT CONSTRUCTION ---------------------------------------------

  constructor(private _translationService: TranslationService) {}

  ngOnInit(): void {
    // check if translations are already loaded (from external app)
    if (!this._translationService.isTranslationsLoaded()) {
      this._translationService.setTranslations(strings);
    }

    if (this.valueAttr.length == 0) {
      console.error(getError(301));
      this.error = true;
    }

    if (!Array.isArray(this.selected)) {
      console.error(getError(303));
      this.error = true;
    }

    // if attributes for label are not set take all attributes from object and show
    if (this.attributesForLabel.length == 0 && this.source.length > 0) {
      this.attributesForLabel = Object.keys(this.source[0]);
    }

    this.setInputValue();
  }

  // ------------------------------------------------------ PRIVATE METHODS ----------------------------------------------------

  private setInputValue() {
    var rowKeys = [];
    this.inputValue = '';

    if (!Array.isArray(this.selected)) rowKeys = [this.selected];
    else rowKeys = [...this.selected];

    rowKeys.forEach((element) => {
      var row = this.source.find((x: any) => x[this.valueAttr] == element);
      if (row) {
        var text = '';
        this.attributesForLabel.forEach((attr) => {
          text += row[attr] + ' ';
        });

        text = text.trim();
        if (this.multiple) this.inputValue += text + '; ';
        else this.inputValue += text;
      }
    });
  }

  // ------------------------------------------------------ PUBLIC METHODS -----------------------------------------------------

  public getSelectedItems(): any[] {
    return this.selectedItems;
  }

  // ------------------------------------------------------ DOM LISTENERS ------------------------------------------------------

  public toggleGridSelect() {
    if (!this.disabled) {
      this.popover.toggle();
      this.gridSelectOpen = this.popover.isShown;
    }
  }

  public getSelectGridWidth(): number {
    if (this.customWidth > 0) return this.customWidth;
    else {
      let width = 100;
      const element: HTMLElement | null = document.getElementById(this.id);
      if (element) width = element.offsetWidth;
      return width;
    }
  }

  public onGridResized() {
    if (this.customWidth == 0)
      this.popoverContext.width = this.getSelectGridWidth();
  }

  public gridSelectionChanged(ev: IGridSelection) {
    this.selected = ev.selectedRows.map((x: any) => x[this.valueAttr]);
    this.setInputValue();

    this.onSelectionChanged.emit({
      selectedKeys: this.selected,
      selectedItems: ev.selectedRows,
    });
  }
}
