import { Component, ElementRef, Input, OnInit, ViewChild } from '@angular/core';
import * as pdfMake from 'pdfmake/build/pdfmake';
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
import htmlToPdfmake from 'html-to-pdfmake';
import { PDF_PAGE_CONF } from '../../../resources/defaults';
import { GRID_DATA_TYPE } from '../../../resources/mode-enums';
import { GridExport } from '../grid-export.class';
import {
  IGridExportDocumentSettings,
  IGridExportHeader,
} from '../../../models/grid.model';

try {
  const pfAny: any = pdfFonts;
  const pmAny: any = pdfMake;
  const __vfs = (pfAny && pfAny.pdfMake && pfAny.pdfMake.vfs) || (pfAny && pfAny.vfs) || pfAny;
  if (pmAny && __vfs) {
    pmAny.vfs = __vfs;
  }
} catch (e) {
  // ignore - vfs may be attached at runtime by the app
}

@Component({
  selector: 'ngx-grid-pdf-export',
  templateUrl: './grid-pdf-export.component.html',
  styleUrls: ['./grid-pdf-export.component.scss'],
})
export class GridPdfExportComponent implements OnInit {
  // ----------------------------------------------------- PRIVATE FIELDS ----------------------------------------------------------

  // ----------------------------------------------------- PUBLIC FIELDS -----------------------------------------------------------

  public headers: IGridExportHeader[] = []; // headers for export table
  public data: any[] = []; // data to be exported
  public specialTypes = GRID_DATA_TYPE; // specialTypes enum

  // ----------------------------------------------------- VIEW CHILD --------------------------------------------------------------

  @ViewChild('content') content!: ElementRef;

  // ----------------------------------------------------- INPUTS ------------------------------------------------------------------

  @Input() settings!: IGridExportDocumentSettings; // settings for export document

  // ----------------------------------------------------- OUTPUTS -----------------------------------------------------------------

  // ----------------------------------------------------- COMPONENT CONSTRUCTION --------------------------------------------------

  constructor() {}

  ngOnInit(): void {}

  // ----------------------------------------------------- PRIVATE METHODS ---------------------------------------------------------

  // ----------------------------------------------------- PUBLIC METHODS ----------------------------------------------------------

  /*
    Exports and downloads provided data in pdf format.
  */
  public exportPdf(data: any, headers: any): void {
    this.headers = headers;
    this.data = data;

    // await for HTML elements to render
    setTimeout(() => {
      const pdfTable = this.content.nativeElement;
      var html = htmlToPdfmake(pdfTable.innerHTML);
      let orientation: string = 'portrait';
      if (this.headers.length > PDF_PAGE_CONF.columnsToPortrait)
        orientation = 'landscape';
      const documentDefinition: any = {
        content: html,
        styles: {
          table: {
            fontSize: PDF_PAGE_CONF.fontSize,
          },
        },
        pageSize: PDF_PAGE_CONF.pageSize,
        pageOrientation: orientation,
        pageMargins: PDF_PAGE_CONF.pageMargins,
      };

      pdfMake.createPdf(documentDefinition).download(this.settings.docName);
    }, 100);
  }

  public getFilename(item: any, header: IGridExportHeader): string {
    return GridExport.getFilename(item, header);
  }

  // ----------------------------------------------------- DOM LISTENERS -----------------------------------------------------------
}
