import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
} from '@angular/core';
import { GridColumn } from '../../models/grid-column.model';
import {
  GRID_BUTTON_TYPE,
  GRID_DATE_PICKER,
  GRID_DATA_TYPE,
} from '../../resources/mode-enums';
import { Subscription } from 'rxjs';
import { getError } from '../../resources/error-codes';
import { HttpClient } from '@angular/common/http';
import { GridColumnEditor } from '../../models/grid-column-editor.model';
import { GridButtonType } from '../../models/grid-button-type.model';
import { TranslationService } from '../../resources/translation.service';

@Component({
  selector: 'ngx-cell-edit',
  templateUrl: './cell-edit.component.html',
  styleUrls: ['./cell-edit.component.scss'],
})
export class CellEditComponent implements OnInit, OnDestroy {
  constructor(
    private http: HttpClient,
    private translationService: TranslationService
  ) {}

  ngOnInit(): void {
    // if data for select is from server perfom http get request
    if (
      this.column.getEditor() == GRID_DATA_TYPE.SELECT ||
      this.column.getEditor() == GRID_DATA_TYPE.AUTOCOMPLETE
    ) {
      var settings = this.column.getEditorSettings();
      if (settings.getServerDataSource())
        this.getDataSourceFromServer(settings);
      else this.selectFilterDataSource = settings.getDataSource();
    }

    // if editor type is date and cellValue is set convert dates to proper format
    if (
      this.column.getEditor() == GRID_DATA_TYPE.DATE_PICKER &&
      this._cellValue
    )
      this.setUpDatePickerValues();
    this.translateEditorDefaultOptions();
  }

  ngOnDestroy(): void {
    this._subs.forEach((element) => {
      element.unsubscribe();
    });
  }

  @Input() isNew: boolean = true;
  @Input() column: GridColumn = new GridColumn();
  @Input() set cellValue(value: any) {
    this._cellValue = value;
    this.cellValueChange.emit(this._cellValue);
  }
  get cellValue(): any {
    return this._cellValue;
  }

  @Output() cellValueChange: EventEmitter<any> = new EventEmitter<any>();
  @Output() cellButtonClick: EventEmitter<GridButtonType> =
    new EventEmitter<GridButtonType>();

  private _subs: Subscription[] = [];
  private _cellValue: any;

  public types = GRID_DATA_TYPE;
  public datePickerTypes = GRID_DATE_PICKER;
  public selectFilterDataSource: any[] = [];
  public btnTypes = GRID_BUTTON_TYPE;

  private getDataSourceFromServer(settings: GridColumnEditor): void {
    this._subs.push(
      this.http
        .get(settings.getServerEndpoint(), {
          params: settings.getServerParams(),
        })
        .subscribe((data: any) => {
          if (data) this.selectFilterDataSource = data;
          else console.error(getError(205));
        })
    );
  }

  private setUpDatePickerValues(): void {
    if (
      this.column.getEditorSettings().getDatePickerType() ==
      GRID_DATE_PICKER.DATE_RANGE
    )
      this._cellValue = {
        start: new Date(this._cellValue.start),
        end: new Date(this._cellValue.end),
      };
    else this._cellValue = new Date(this._cellValue);
  }

  public onButtonClick(btn: GridButtonType): void {
    this.cellButtonClick.emit(btn);
  }

  private translateEditorDefaultOptions() {
    var editor = this.column.getEditorSettings() as any;

    if (!editor._ClearText)
      editor._ClearText =
        this.translationService.translate('gridFilterShowAll');
    if (!editor._ApplyButtonText)
      editor._ApplyButtonText = this.translationService.translate(
        'gridDatepickerApplyBtn'
      );
    if (!editor._CurrentTimeButtonText)
      editor._CurrentTimeButtonText =
        this.translationService.translate('gridDatepickerNow');
    if (!editor._TimeText)
      editor._TimeText =
        this.translationService.translate('gridDatepickerAmPm');
    if (!editor._HoursText)
      editor._HoursText = this.translationService.translate(
        'gridDatepickerHours'
      );
    if (!editor._MinutesText)
      editor._MinutesText = this.translationService.translate(
        'gridDatepickerMinutes'
      );
    if (!editor._SecondsText)
      editor._SecondsText = this.translationService.translate(
        'gridDatepickerSeconds'
      );
  }
}
